def load_risk_config(path: Optional[Path] = None) -> Dict[str, Any]:
    """Loads config/polymarket_risk_config.json merged over safe defaults.

    Fail-safe: a missing/corrupt file or a non-finite/non-positive numeric value falls back to the
    conservative built-in default for that key (never to a looser legacy limit).
    """
    cfg: Dict[str, Any] = dict(_RISK_CONFIG_DEFAULTS)
    try:
        with open(path or RISK_CONFIG_PATH, "r", encoding="utf-8") as fh:
            raw = json.load(fh)
        if isinstance(raw, dict):
            for key, default in _RISK_CONFIG_DEFAULTS.items():
                if key not in raw:
                    continue
                val = raw[key]
                if isinstance(default, bool):
                    cfg[key] = bool(val)
                elif key == "exit_policy" and isinstance(val, str) and val in ("hold_98", "two_tranche_95_98"):
                    cfg[key] = val
                elif key == "d1_routing_mode" and isinstance(val, str) and val in ("hybrid_auto", "fragile_first", "parallel_2leg"):
                    cfg[key] = val
                elif isinstance(val, (int, float)) and not isinstance(val, bool) and math.isfinite(float(val)) and (float(val) >= 0.0 if key == "d1_box_collateral_reserve_usd" else float(val) > 0):
                    cfg[key] = int(val) if key in ("max_concurrent_positions", "seed_survival_max_concurrent", "max_concurrent_d1_boxes", "max_total_portfolio_slots") else float(val)
    except Exception:
        pass
    return cfg

RISK_CONFIG: Dict[str, Any] = load_risk_config()

