    @classmethod
    def encode_pusd_wrap_calls(
        cls,
        *,
        funder_address: str,
        amount_raw: int,
        current_allowance_raw: int,
    ) -> List[Tuple[str, str]]:
        """ABI-encodes `[optional USDC.e.approve(PUSD_WRAPPER, MAX_UINT256), PUSD_WRAPPER.wrap(USDC.e, funder, amount)]`."""
        amt = int(amount_raw or 0)
        if amt <= 0 or not funder_address:
            return []
        from web3 import Web3
        funder_cs = Web3.to_checksum_address(funder_address)
        usdce_cs = Web3.to_checksum_address(cls.USDC_E_ADDRESS)
        wrapper_cs = Web3.to_checksum_address(cls.PUSD_WRAPPER_ADDRESS)
        calls: List[Tuple[str, str]] = []
        if int(current_allowance_raw or 0) < amt:
            calls.append((usdce_cs, f"0x095ea7b3{wrapper_cs[2:].lower().rjust(64, '0')}{'f' * 64}"))
        calls.append((
            wrapper_cs,
            f"0x62355638{usdce_cs[2:].lower().rjust(64, '0')}{funder_cs[2:].lower().rjust(64, '0')}{amt:064x}",
        ))
        return calls

    def sync_clob_collateral_allowance(self) -> bool:
        """Invalidates local collateral cache and notifies Polymarket CLOB L2 of updated on-chain pUSD balance."""
        self.invalidate_collateral_cache()
        try:
            raw_sig_type = getattr(self, "signature_type", None)
            sig_type = 1 if raw_sig_type is None else int(raw_sig_type)
            if getattr(self, "client", None) is not None and BalanceAllowanceParams is not None and AssetType is not None:
                self.client.update_balance_allowance(
                    BalanceAllowanceParams(asset_type=AssetType.COLLATERAL, signature_type=sig_type)
                )
                return True
        except Exception:
            pass
        return False

    @staticmethod
    def _payout_redemption_topic() -> str:
        from eth_utils import keccak
        return "0x" + keccak(text="PayoutRedemption(address,address,bytes32,bytes32,uint256[],uint256)").hex().replace("0x", "")

    @staticmethod
    def _neg_risk_payout_redemption_topic() -> str:
        from eth_utils import keccak
        return "0x" + keccak(text="PayoutRedemption(address,bytes32,uint256[],uint256)").hex().replace("0x", "")

    @staticmethod
    def build_relayer_builder_headers(
        api_key: str,
        secret: str,
        passphrase: str,
        method: str,
        request_path: str,
        body: Any = None,
        timestamp: Optional[int] = None,
    ) -> Dict[str, str]:
        """
        Generates exact Polymarket Relayer V2 HMAC headers matching `py-builder-signing-sdk`
        bit-for-bit (`POLY_BUILDER_API_KEY`, `POLY_BUILDER_TIMESTAMP`, `POLY_BUILDER_PASSPHRASE`,
        `POLY_BUILDER_SIGNATURE`).
        """
        import base64
        import hashlib
        import hmac

        ts_str = str(int(timestamp if timestamp is not None else time.time()))
        raw_secret = base64.urlsafe_b64decode(secret)
        msg = ts_str + str(method) + str(request_path)
        if body is not None:
            if isinstance(body, (bytes, bytearray)):
                msg += body.decode("utf-8")
            elif isinstance(body, str):
                msg += body
            else:
                msg += str(body).replace("'", '"')
        sig = base64.urlsafe_b64encode(
            hmac.new(raw_secret, msg.encode("utf-8"), hashlib.sha256).digest()
        ).decode("utf-8")
        return {
            "POLY_BUILDER_API_KEY": api_key,
            "POLY_BUILDER_TIMESTAMP": ts_str,
            "POLY_BUILDER_PASSPHRASE": passphrase,
            "POLY_BUILDER_SIGNATURE": sig,
        }

    @classmethod
    def build_deposit_wallet_relayer_batch(
        cls,
        *,
        private_key: str,
        wallet_address: str,
        nonce: int,
        deadline: int,
        calls: List[Dict[str, str]],
        chain_id: int = 137,
    ) -> Dict[str, Any]:
        """
        Constructs and EIP-712 signs a `DepositWallet` (`signature_type=3` / `POLY_1271`)
        `WALLET` batch payload matching Polymarket's `DepositWallet` contract
        (`Batch(address wallet,uint256 nonce,uint256 deadline,Call[] calls)Call(address target,uint256 value,bytes data)`).
        """
        from eth_account import Account
        from eth_account.messages import encode_typed_data
        from web3 import Web3

        wallet_cs = Web3.to_checksum_address(wallet_address)
        signer_cs = Web3.to_checksum_address(Account.from_key(private_key).address)
        factory_cs = Web3.to_checksum_address(cls.DEPOSIT_WALLET_FACTORY)
        norm_calls = []
        typed_calls = []
        for c in calls:
            tgt_cs = Web3.to_checksum_address(c["target"])
            val_str = str(int(c.get("value", "0") or 0))
            data_hex = str(c["data"]) if str(c["data"]).startswith("0x") else ("0x" + str(c["data"]))
            norm_calls.append({"target": tgt_cs, "value": val_str, "data": data_hex})
            typed_calls.append({"target": tgt_cs, "value": int(val_str), "data": bytes.fromhex(data_hex[2:])})

        typed_msg = {
            "types": {
                "EIP712Domain": [
                    {"name": "name", "type": "string"},
                    {"name": "version", "type": "string"},
                    {"name": "chainId", "type": "uint256"},
                    {"name": "verifyingContract", "type": "address"},
                ],
                "Call": [
                    {"name": "target", "type": "address"},
                    {"name": "value", "type": "uint256"},
                    {"name": "data", "type": "bytes"},
                ],
                "Batch": [
                    {"name": "wallet", "type": "address"},
                    {"name": "nonce", "type": "uint256"},
                    {"name": "deadline", "type": "uint256"},
                    {"name": "calls", "type": "Call[]"},
                ],
            },
            "primaryType": "Batch",
            "domain": {
                "name": "DepositWallet",
                "version": "1",
                "chainId": int(chain_id),
                "verifyingContract": wallet_cs,
            },
            "message": {
                "wallet": wallet_cs,
                "nonce": int(nonce),
                "deadline": int(deadline),
                "calls": typed_calls,
            },
        }
        signable = encode_typed_data(full_message=typed_msg)
        raw_sig = Account.sign_message(signable, private_key=private_key).signature.hex()
        sig_hex = raw_sig if raw_sig.startswith("0x") else f"0x{raw_sig}"
        return {
            "type": "WALLET",
            "from": signer_cs,
            "to": factory_cs,
            "nonce": str(int(nonce)),
            "signature": sig_hex,
            "depositWalletParams": {
                "depositWallet": wallet_cs,
                "deadline": str(int(deadline)),
                "calls": norm_calls,
            },
        }

    def _rpc(self, method: str, params: list) -> Optional[Any]:
        primary = (os.getenv("POLYGON_RPC_URL") or "https://polygon-bor-rpc.publicnode.com").strip()
        rpcs: List[str] = []
        for u in (primary, "https://polygon-bor-rpc.publicnode.com", "https://polygon-rpc.com", "https://1rpc.io/matic"):
            if u and u not in rpcs:
                rpcs.append(u)
        session = getattr(self, "_sync_session", requests)
        for rpc_url in rpcs:
            try:
                resp = session.post(rpc_url, json={"jsonrpc": "2.0", "id": 1, "method": method, "params": params}, timeout=4.0)
                if resp.status_code != 200:
                    continue
                body = resp.json()
                if not isinstance(body, dict) or "error" in body:
                    continue
                res = body.get("result")
                if res is None:
                    continue
                return res
            except Exception as e:
                logger.debug(f"RPC {method} via {rpc_url} failed: {e}")
        return None

    def get_current_block_number(self) -> Optional[int]:
        res = self._rpc("eth_blockNumber", [])
        try:
            return int(res, 16) if res else None
        except (TypeError, ValueError):
            return None

    def parse_payout_redemption_logs(self, logs: List[Dict[str, Any]], condition_id: str) -> List[Dict[str, Any]]:
        """
        Extracts this account's PayoutRedemption events for `condition_id` (payout in USD),
        supporting standard ConditionalTokens (`CTF_ADDRESS`), `NegRiskAdapter`
        (`NEG_RISK_ADAPTER_ADDRESS`), and Polymarket `AutoRedeemer` (`AUTOREDEEMER_ADDRESS`).
        """
        out = []
        ctf_topic0 = self._payout_redemption_topic().lower()
        nr_topic0 = self._neg_risk_payout_redemption_topic().lower()
        v2_topic0 = self.V2_ADAPTER_REDEMPTION_TOPIC0.lower()
        v2_addrs = {self.CTF_ADAPTER_V2_ADDRESS.lower(), self.NEG_RISK_ADAPTER_V2_ADDRESS.lower()}
        ar_topics = {self.AUTO_REDEEM_CTF_TOPIC0.lower(), self.AUTO_REDEEM_NEGRISK_TOPIC0.lower()}
        me = str(self.funder_address or "").lower().replace("0x", "").rjust(64, "0")
        cond = str(condition_id or "").lower().replace("0x", "").rjust(64, "0")
        seen_keys: set = set()
        for lg in logs or []:
            topics = [str(t).lower() for t in (lg.get("topics") or [])]
            addr = str(lg.get("address", "")).lower()
            data = str(lg.get("data", "")).replace("0x", "")
            if len(topics) >= 2 and topics[0] == ctf_topic0 and addr == self.CTF_ADDRESS.lower():
                if topics[1].replace("0x", "").rjust(64, "0") != me:
                    continue
                if len(data) < 192 or data[0:64] != cond:
                    continue
                payout = int(data[128:192], 16) / 1e6
            elif len(topics) >= 3 and topics[0] == nr_topic0 and addr == self.NEG_RISK_ADAPTER_ADDRESS.lower():
                if topics[1].replace("0x", "").rjust(64, "0") != me:
                    continue
                if topics[2].replace("0x", "").rjust(64, "0") != cond:
                    continue
                if len(data) < 128:
                    continue
                payout = int(data[64:128], 16) / 1e6
            elif len(topics) >= 3 and topics[0] == v2_topic0 and addr in v2_addrs:
                if topics[1].replace("0x", "").rjust(64, "0") != me:
                    continue
                if topics[2].replace("0x", "").rjust(64, "0") != cond:
                    continue
                if len(data) < 128:
                    continue
                payout = int(data[64:128], 16) / 1e6
            elif len(topics) >= 3 and topics[0] in ar_topics and addr == self.AUTOREDEEMER_ADDRESS.lower():
                if topics[1].replace("0x", "").rjust(64, "0") != me:
                    continue
                if topics[2].replace("0x", "").rjust(64, "0") != cond:
                    continue
                if len(data) < 64:
                    continue
                payout = int.from_bytes(bytes.fromhex(data[0:64]), "big") / 1e6
            else:
                continue
            dedupe_k = (lg.get("transactionHash"), lg.get("logIndex"))
            if dedupe_k != (None, None) and dedupe_k in seen_keys:
                continue
            seen_keys.add(dedupe_k)
            out.append({
                "transaction_hash": lg.get("transactionHash"),
                "block_number": int(str(lg.get("blockNumber", "0x0")), 16) if str(lg.get("blockNumber", "")).startswith("0x") else lg.get("blockNumber"),
                "payout_usd": payout,
                "log_index": lg.get("logIndex"),
            })
        return out

    def find_redemption_payouts(
        self,
        condition_id: str,
        from_block: Optional[int] = None,
        tx_hash: Optional[str] = None,
        max_span: int = 15000,
    ) -> Optional[List[Dict[str, Any]]]:
        """
        Returns verified PayoutRedemption receipts for this account and condition, either
        from a specific transaction receipt or by scanning logs from `from_block` across
        standard `CTF`, `NegRiskAdapter`, and `AutoRedeemer`.
        None = could not verify (RPC unavailable); [] = verified absence.
        """
        if self.dry_run or not self.funder_address or not condition_id:
            return None
        if tx_hash:
            receipt = self._rpc("eth_getTransactionReceipt", [tx_hash])
            if not receipt:
                return None
            if str(receipt.get("status", "")).lower() not in {"0x1", "1"}:
                return []
            return self.parse_payout_redemption_logs(receipt.get("logs", []), condition_id)
        head = self.get_current_block_number()
        if head is None:
            return None
        lookback = max(int(max_span), 15000)
        chunk_span = min(int(max_span), 1000) if int(max_span) > 0 else 1000
        start = max(int(from_block), max(0, head - max(lookback, 50000))) if from_block else max(0, head - lookback)
        raw_logs: List[Dict[str, Any]] = []
        me_topic = "0x" + str(self.funder_address).lower().replace("0x", "").rjust(64, "0")
        cond_topic = "0x" + str(condition_id).lower().replace("0x", "").rjust(64, "0")
        ar_topic0_or = [self.AUTO_REDEEM_CTF_TOPIC0, self.AUTO_REDEEM_NEGRISK_TOPIC0]
        cursor = start
        while cursor <= head:
            end = min(head, cursor + chunk_span)
            logs = self._rpc("eth_getLogs", [{
                "address": self.CTF_ADDRESS,
                "fromBlock": hex(cursor),
                "toBlock": hex(end),
                "topics": [self._payout_redemption_topic(), me_topic],
            }])
            if logs is None:
                return None
            if logs:
                raw_logs.extend(logs)
            nr_logs = self._rpc("eth_getLogs", [{
                "address": self.NEG_RISK_ADAPTER_ADDRESS,
                "fromBlock": hex(cursor),
                "toBlock": hex(end),
                "topics": [self._neg_risk_payout_redemption_topic(), me_topic, cond_topic],
            }])
            if nr_logs is None:
                return None
            if nr_logs:
                raw_logs.extend(nr_logs)
            ar_logs = self._rpc("eth_getLogs", [{
                "address": self.AUTOREDEEMER_ADDRESS,
                "fromBlock": hex(cursor),
                "toBlock": hex(end),
                "topics": [ar_topic0_or, me_topic, cond_topic],
            }])
            if ar_logs is None:
                return None
            if ar_logs:
                raw_logs.extend(ar_logs)
            for v2_addr in (self.CTF_ADAPTER_V2_ADDRESS, self.NEG_RISK_ADAPTER_V2_ADDRESS):
                v2_logs = self._rpc("eth_getLogs", [{
                    "address": v2_addr,
                    "fromBlock": hex(cursor),
                    "toBlock": hex(end),
                    "topics": [self.V2_ADAPTER_REDEMPTION_TOPIC0, me_topic, cond_topic],
                }])
                if isinstance(v2_logs, list) and v2_logs:
                    raw_logs.extend(v2_logs)
            cursor = end + 1
        return self.parse_payout_redemption_logs(raw_logs, condition_id)

    def _submit_deposit_wallet_relayer_redemption(
        self, *, pk: str, funder_cs: str, nonce: int, calls: List[Dict[str, str]], condition_id: str,
    ) -> Optional[str]:
        """Submits gasless DepositWallet (sig_type=3) redemption batch via Relayer V2 with wire-byte HMAC & receipt verification."""
        b_key = (os.getenv("POLY_BUILDER_API_KEY") or os.getenv("BUILDER_API_KEY") or "").strip()
        b_sec = (os.getenv("POLY_BUILDER_SECRET") or os.getenv("BUILDER_SECRET") or "").strip()
        b_pass = (os.getenv("POLY_BUILDER_PASSPHRASE") or os.getenv("BUILDER_PASS_PHRASE") or "").strip()
        if not (b_key and b_sec and b_pass):
            return None
        is_recycle_op = str(condition_id or "").startswith(("nrconv:", "nr3:", "split:", "merge:", "batch_merge:", "wrap:", "wrap_pusd"))
        cooldown_map = getattr(self, "_relayer_redemption_cooldown", None)
        if cooldown_map is None:
            self._relayer_redemption_cooldown = cooldown_map = {}
        now_s = time.time()
        if (not is_recycle_op) and float(cooldown_map.get(condition_id, 0.0)) > now_s:
            return None
        rate_gov = getattr(self, "_relayer_rate_limiter", None)
        if rate_gov is None:
            rate_gov = RelayerRateLimiter(max_per_min=24, window_sec=60.0)
            self._relayer_rate_limiter = rate_gov
        if (not is_recycle_op) and rate_gov.recent_count() >= max(1, int(rate_gov.max_per_min) - 1):
            logger.warning(
                f"[RELAYER-GOVERNOR] Deferring passive Relayer V2 /submit for {condition_id}: reserving slot {rate_gov.max_per_min}/min for post-fill recycle ops."
            )
            return None
        allowed_rl, retry_rl = rate_gov.allow_and_record()
        if not allowed_rl:
            logger.warning(
                f"[RELAYER-GOVERNOR] Deferring Relayer V2 /submit for {condition_id}: 24/min safety cap reached (retry in {retry_rl:.2f}s)."
            )
            return None
        relayer_base = os.getenv("POLY_RELAYER_URL", self.RELAYER_V2_URL).rstrip("/")
        req_dict = self.build_deposit_wallet_relayer_batch(
            private_key=pk, wallet_address=funder_cs, nonce=nonce, deadline=int(now_s) + 300, calls=calls, chain_id=self.CHAIN_ID,
        )
        body_json = json.dumps(req_dict, separators=(",", ":"))
        headers = self.build_relayer_builder_headers(
            api_key=b_key, secret=b_sec, passphrase=b_pass, method="POST", request_path="/submit", body=body_json,
        )
        headers["Content-Type"] = "application/json"
        session = getattr(self, "_sync_session", requests)
        resp = session.post(f"{relayer_base}/submit", headers=headers, data=body_json.encode("utf-8"), timeout=8.0)
        if resp.status_code != 200:
            logger.warning(f"[REDEMPTION] Relayer V2 submit HTTP {resp.status_code}: {resp.text[:200]}")
            return None
        body = resp.json() if resp.content else {}
        if body.get("state") in ("STATE_FAILED", "STATE_INVALID"):
            return None
        if not is_recycle_op:
            cooldown_map[condition_id] = now_s + 30.0
        tx_hash = body.get("transactionHash")
        tx_id = body.get("transactionID")
        if not tx_hash and tx_id:
            for _ in range(3):
                time.sleep(1.5)
                tr = session.get(f"{relayer_base}/transaction", params={"id": tx_id}, timeout=5.0)
                if tr.status_code == 200:
                    t_list = tr.json()
                    if isinstance(t_list, list) and t_list:
                        if t_list[0].get("state") in ("STATE_FAILED", "STATE_INVALID"):
                            return None
                        tx_hash = t_list[0].get("transactionHash")
                        if tx_hash:
                            break
        if tx_hash:
            tx_hash_norm = tx_hash if str(tx_hash).startswith("0x") else f"0x{tx_hash}"
            for attempt_rcpt in range(3):
                receipt = self._rpc("eth_getTransactionReceipt", [tx_hash_norm])
                if isinstance(receipt, dict) and receipt.get("status") is not None:
                    if str(receipt.get("status", "")).lower() not in {"0x1", "1"}:
                        return None
                    if not is_recycle_op:
                        cooldown_map[condition_id] = time.time() + 180.0
                    break
                if attempt_rcpt < 2 and session is requests:
                    time.sleep(1.2)
            return tx_hash_norm
        return None

    def attempt_onchain_redemption(self, condition_id: str, *, neg_risk: Optional[bool] = None) -> Optional[str]:
        """R01 Multi-Wallet & Multi-Adapter Redemption Engine (EOA=0, Proxy=1, Safe=2, DepositWallet=3)."""
        raw_sig_type = getattr(self, "signature_type", None)
        sig_type = 1 if raw_sig_type is None else int(raw_sig_type)
        if self.dry_run or not condition_id or sig_type not in (0, 1, 2, 3):
            return None
        b_key = (os.getenv("POLY_BUILDER_API_KEY") or os.getenv("BUILDER_API_KEY") or "").strip()
        if sig_type == 3 and not b_key:
            self._funder_is_gnosis_safe = False
            now_warn = time.time()
            if (now_warn - float(getattr(self, "_last_missing_builder_key_warn_ts", 0.0))) >= 3600.0:
                self._last_missing_builder_key_warn_ts = now_warn
                logger.warning(f"[REDEMPTION] DepositWallet ({self.funder_address}) requires POLY_BUILDER_API_KEY for Relayer V2.")
            return None
        if sig_type == 2 and getattr(self, "_funder_is_gnosis_safe", None) is False:
            return None
        pk = (os.getenv("POLYGON_PRIVATE_KEY") or self.private_key or "").strip()
        if not pk or not self.funder_address:
            return None
        try:
            from web3 import Web3
            from src.polymarket_research.riskless_machine_gun_engine import get_fast_polygon_web3
            w3 = get_fast_polygon_web3(timeout=5.0)
            funder_cs = Web3.to_checksum_address(self.funder_address)
            signer_cs = Web3.to_checksum_address(w3.eth.account.from_key(pk).address)
            if sig_type in (0, 1, 2):
                gas_payer_cs = funder_cs if sig_type == 0 else signer_cs
                if w3.eth.get_balance(gas_payer_cs) < int(0.05 * 1e18):
                    return None

            cond_bytes = bytes.fromhex(condition_id.lower().replace("0x", "").rjust(64, "0"))
            ctf_abi = [
                {"inputs": [{"name": "collateralToken", "type": "address"}, {"name": "parentCollectionId", "type": "bytes32"}, {"name": "conditionId", "type": "bytes32"}, {"name": "indexSets", "type": "uint256[]"}], "name": "redeemPositions", "outputs": [], "stateMutability": "nonpayable", "type": "function"},
                {"inputs": [{"name": "parentCollectionId", "type": "bytes32"}, {"name": "conditionId", "type": "bytes32"}, {"name": "indexSet", "type": "uint256"}], "name": "getCollectionId", "outputs": [{"name": "", "type": "bytes32"}], "stateMutability": "view", "type": "function"},
                {"inputs": [{"name": "collateralToken", "type": "address"}, {"name": "collectionId", "type": "bytes32"}], "name": "getPositionId", "outputs": [{"name": "", "type": "uint256"}], "stateMutability": "pure", "type": "function"},
                {"inputs": [{"name": "owner", "type": "address"}, {"name": "id", "type": "uint256"}], "name": "balanceOf", "outputs": [{"name": "", "type": "uint256"}], "stateMutability": "view", "type": "function"},
                {"inputs": [{"name": "conditionId", "type": "bytes32"}], "name": "payoutDenominator", "outputs": [{"name": "", "type": "uint256"}], "stateMutability": "view", "type": "function"},
                {"inputs": [{"name": "conditionId", "type": "bytes32"}, {"name": "index", "type": "uint256"}], "name": "payoutNumerators", "outputs": [{"name": "", "type": "uint256"}], "stateMutability": "view", "type": "function"},
            ]
            nr_abi = [
                {"inputs": [{"name": "_conditionId", "type": "bytes32"}, {"name": "_amounts", "type": "uint256[]"}], "name": "redeemPositions", "outputs": [], "stateMutability": "nonpayable", "type": "function"},
            ]
            ctf_cs = Web3.to_checksum_address(self.CTF_ADDRESS)
            ctf = w3.eth.contract(address=ctf_cs, abi=ctf_abi)
            nr_cs = Web3.to_checksum_address(self.NEG_RISK_ADAPTER_ADDRESS)
            nr_contract = w3.eth.contract(address=nr_cs, abi=nr_abi)

            # Never submit redemption before oracle payout vector is finalized on-chain
            payout_den = 0
            payout_nums: Optional[Tuple[int, int]] = None
            try:
                payout_den = int(ctf.functions.payoutDenominator(cond_bytes).call())
                if payout_den <= 0:
                    return None
                n0 = int(ctf.functions.payoutNumerators(cond_bytes, 0).call())
                n1 = int(ctf.functions.payoutNumerators(cond_bytes, 1).call())
                if 0 <= n0 <= payout_den and 0 <= n1 <= payout_den and (n0 + n1) <= payout_den:
                    payout_nums = (n0, n1)
            except Exception:
                pass

            # Build candidate (target_contract, inner_calldata_hex) calls that hold positive redeemable inventory
            redeem_targets: List[Tuple[str, str]] = []
            expected_usdce_delta_raw = 0
            needs_post_wrap = False
            # 1. Check NegRisk WrappedCollateral positions first when neg_risk is True or unknown (unwraps to USDC.e)
            if neg_risk is not False:
                try:
                    wcol_cs = Web3.to_checksum_address(self.NEG_RISK_WRAPPED_COLLATERAL)
                    b_yes = int(ctf.functions.balanceOf(funder_cs, ctf.functions.getPositionId(wcol_cs, ctf.functions.getCollectionId(b"\x00" * 32, cond_bytes, 1).call()).call()).call())
                    b_no = int(ctf.functions.balanceOf(funder_cs, ctf.functions.getPositionId(wcol_cs, ctf.functions.getCollectionId(b"\x00" * 32, cond_bytes, 2).call()).call()).call())
                    if b_yes > 0 or b_no > 0:
                        nr_hex = (
                            nr_contract.encode_abi("redeemPositions", args=[cond_bytes, [b_yes, b_no]])
                            if hasattr(nr_contract, "encode_abi")
                            else nr_contract.encodeABI(fn_name="redeemPositions", args=[cond_bytes, [b_yes, b_no]])
                        )
                        redeem_targets.append((nr_cs, nr_hex))
                        needs_post_wrap = True
                        if payout_nums is not None and payout_den > 0:
                            expected_usdce_delta_raw += (b_yes * payout_nums[0]) // payout_den + (b_no * payout_nums[1]) // payout_den
                except Exception:
                    pass

            # 2. Check standard CTF positions (Polymarket V2 pUSD + legacy USDC.e)
            if neg_risk is not True:
                for col_hex in (
                    self.PUSD_ADDRESS,
                    self.USDC_E_ADDRESS,
                ):
                    try:
                        col_cs = Web3.to_checksum_address(col_hex)
                        b_idx = [
                            int(ctf.functions.balanceOf(funder_cs, ctf.functions.getPositionId(col_cs, ctf.functions.getCollectionId(b"\x00" * 32, cond_bytes, idx).call()).call()).call())
                            for idx in (1, 2)
                        ]
                        if b_idx[0] > 0 or b_idx[1] > 0:
                            ctf_hex = (
                                ctf.encode_abi("redeemPositions", args=[col_cs, b"\x00" * 32, cond_bytes, [1, 2]])
                                if hasattr(ctf, "encode_abi")
                                else ctf.encodeABI(fn_name="redeemPositions", args=[col_cs, b"\x00" * 32, cond_bytes, [1, 2]])
                            )
                            redeem_targets.append((ctf_cs, ctf_hex))
                            if col_cs.lower() == self.USDC_E_ADDRESS.lower():
                                needs_post_wrap = True
                                if payout_nums is not None and payout_den > 0:
                                    expected_usdce_delta_raw += (b_idx[0] * payout_nums[0]) // payout_den + (b_idx[1] * payout_nums[1]) // payout_den
                    except Exception:
                        continue

            if not redeem_targets:
                return None

            wrapped_inline = False
            tx_h: Optional[str] = None
            if sig_type in (1, 3) and expected_usdce_delta_raw > 0:
                try:
                    erc20_abi = [
                        {"inputs": [{"name": "a", "type": "address"}], "name": "balanceOf", "outputs": [{"name": "", "type": "uint256"}], "stateMutability": "view", "type": "function"},
                        {"inputs": [{"name": "o", "type": "address"}, {"name": "s", "type": "address"}], "name": "allowance", "outputs": [{"name": "", "type": "uint256"}], "stateMutability": "view", "type": "function"},
                    ]
                    usdce_c = w3.eth.contract(address=Web3.to_checksum_address(self.USDC_E_ADDRESS), abi=erc20_abi)
                    pre_usdce_raw = max(0, int(usdce_c.functions.balanceOf(funder_cs).call()))
                    alw_raw = max(0, int(usdce_c.functions.allowance(funder_cs, Web3.to_checksum_address(self.PUSD_WRAPPER_ADDRESS)).call()))
                    wrap_calls = self.encode_pusd_wrap_calls(
                        funder_address=funder_cs,
                        amount_raw=pre_usdce_raw + expected_usdce_delta_raw,
                        current_allowance_raw=alw_raw,
                    )
                    if wrap_calls:
                        tx_h = self._dispatch_funder_calls(
                            w3, Web3, pk, sig_type, funder_cs, signer_cs, redeem_targets + wrap_calls, condition_id
                        )
                        if tx_h:
                            wrapped_inline = True
                except Exception:
                    tx_h = None

            if not tx_h:
                tx_h = self._dispatch_funder_calls(
                    w3, Web3, pk, sig_type, funder_cs, signer_cs, redeem_targets, condition_id
                )
            if not tx_h:
                return None

            wait_fn = getattr(w3.eth, "wait_for_transaction_receipt", None)
            mined_ok = False
            if callable(wait_fn):
                try:
                    rc = wait_fn(tx_h, timeout=30, poll_latency=1.2)
                    if isinstance(rc, dict) and rc.get("status") is not None:
                        if int(rc.get("status", 0)) != 1:
                            return None
                        mined_ok = True
                except Exception:
                    pass
            if mined_ok and needs_post_wrap and not wrapped_inline:
                self.wrap_idle_usdce_to_pusd(min_usd=0.50)
            self.sync_clob_collateral_allowance()
            return tx_h
        except Exception as e:
            logger.debug(f"On-chain redemption skipped for {condition_id}: {e}")
            return None

    def get_idle_usdce_balance(self) -> Optional[float]:
        """Read-only Polygon ERC-20 `USDC.e` balance check on `funder_address` (prevents false ruin halts prior to pUSD wrap)."""
        if self.dry_run or not self.funder_address:
            return 0.0
        try:
            from web3 import Web3
            from src.polymarket_research.riskless_machine_gun_engine import get_fast_polygon_web3

            w3 = get_fast_polygon_web3(timeout=3.5)
            funder_cs = Web3.to_checksum_address(self.funder_address)
            usdce_cs = Web3.to_checksum_address(self.USDC_E_ADDRESS)
            erc20_abi = [
                {"inputs": [{"name": "a", "type": "address"}], "name": "balanceOf", "outputs": [{"name": "", "type": "uint256"}], "stateMutability": "view", "type": "function"}
            ]
            bal_raw = int(w3.eth.contract(address=usdce_cs, abi=erc20_abi).functions.balanceOf(funder_cs).call())
            return round(max(0.0, bal_raw / 1e6), 6)
        except Exception:
            return None

    def wrap_idle_usdce_to_pusd(self, min_usd: float = 1.0) -> Dict[str, Any]:
        """
        Sweeps idle legacy Polygon `USDC.e` (`0x2791...`) sitting in `funder_address` 1:1 into
        Polymarket V2 `pUSD` (`0xC011...`) via `PUSD_WRAPPER_ADDRESS` (`0x9307...`, selector `0x62355638`)
        and immediately syncs CLOB L2 collateral allowance.
        """
        raw_sig_type = getattr(self, "signature_type", None)
        sig_type = 1 if raw_sig_type is None else int(raw_sig_type)
        if self.dry_run:
            return {"wrapped": False, "dry_run": True, "amount_usd": 0.0, "tx_hash": None}
        pk = (os.getenv("POLYGON_PRIVATE_KEY") or self.private_key or "").strip()
        if sig_type not in (0, 1, 2, 3) or not pk or not self.funder_address:
            return {"wrapped": False, "amount_usd": 0.0, "tx_hash": None, "reason": "UNCONFIGURED"}
        b_key = (os.getenv("POLY_BUILDER_API_KEY") or os.getenv("BUILDER_API_KEY") or "").strip()
        if sig_type == 3 and not b_key:
            return {"wrapped": False, "amount_usd": 0.0, "tx_hash": None, "reason": "MISSING_BUILDER_KEY"}
        if sig_type == 2 and getattr(self, "_funder_is_gnosis_safe", None) is False:
            return {"wrapped": False, "amount_usd": 0.0, "tx_hash": None, "reason": "NOT_GNOSIS_SAFE"}
        try:
            from web3 import Web3
            from src.polymarket_research.riskless_machine_gun_engine import get_fast_polygon_web3
            w3 = get_fast_polygon_web3(timeout=5.0)
            funder_cs = Web3.to_checksum_address(self.funder_address)
            signer_cs = Web3.to_checksum_address(w3.eth.account.from_key(pk).address)
            if sig_type in (0, 1, 2):
                gas_payer_cs = funder_cs if sig_type == 0 else signer_cs
                if w3.eth.get_balance(gas_payer_cs) < int(0.05 * 1e18):
                    return {"wrapped": False, "amount_usd": 0.0, "tx_hash": None, "reason": "INSUFFICIENT_GAS"}
            erc20_abi = [
                {"inputs": [{"name": "a", "type": "address"}], "name": "balanceOf", "outputs": [{"name": "", "type": "uint256"}], "stateMutability": "view", "type": "function"},
                {"inputs": [{"name": "o", "type": "address"}, {"name": "s", "type": "address"}], "name": "allowance", "outputs": [{"name": "", "type": "uint256"}], "stateMutability": "view", "type": "function"},
            ]
            usdce_cs = Web3.to_checksum_address(self.USDC_E_ADDRESS)
            wrapper_cs = Web3.to_checksum_address(self.PUSD_WRAPPER_ADDRESS)
            usdce_c = w3.eth.contract(address=usdce_cs, abi=erc20_abi)
            bal_raw = int(usdce_c.functions.balanceOf(funder_cs).call())
            min_raw = max(1, int(math.floor(max(0.000001, float(min_usd)) * 1e6)))
            if bal_raw < min_raw:
                return {"wrapped": False, "amount_usd": round(bal_raw / 1e6, 6), "tx_hash": None, "reason": "BELOW_MIN_USD"}
            alw_raw = int(usdce_c.functions.allowance(funder_cs, wrapper_cs).call())
            wrap_calls = self.encode_pusd_wrap_calls(
                funder_address=funder_cs, amount_raw=bal_raw, current_allowance_raw=alw_raw
            )
            tx_h = self._dispatch_funder_calls(
                w3, Web3, pk, sig_type, funder_cs, signer_cs, wrap_calls, "wrap_pusd"
            )
            if not tx_h:
                return {"wrapped": False, "amount_usd": round(bal_raw / 1e6, 6), "tx_hash": None, "reason": "DISPATCH_DEFERRED"}
            rc = w3.eth.wait_for_transaction_receipt(tx_h, timeout=60, poll_latency=1.2)
            if int(rc.get("status", 0)) != 1:
                logger.warning(f"[PUSD-WRAP] wrap tx {tx_h} reverted for ${bal_raw / 1e6:.2f} USDC.e.")
                return {"wrapped": False, "amount_usd": round(bal_raw / 1e6, 6), "tx_hash": tx_h, "reason": "TX_REVERTED"}
            self.sync_clob_collateral_allowance()
            amt_usd = round(bal_raw / 1e6, 6)
            logger.info(f"✓ [PUSD-WRAP] Wrapped ${amt_usd:.2f} idle USDC.e -> pUSD | tx={tx_h}")
            return {"wrapped": True, "amount_usd": amt_usd, "tx_hash": tx_h}
        except Exception as exc:
            logger.debug(f"[PUSD-WRAP] Idle USDC.e wrap check skipped: {exc}")
            return {"wrapped": False, "amount_usd": 0.0, "tx_hash": None, "reason": str(exc)}

    def attempt_wrap_legacy_usdce_to_pusd(self, *, min_usd: float = 1.0) -> Dict[str, Any]:
        """Alias wrapper returning unified `success`/`wrapped_usd`/`tx_hash` keys alongside `wrap_idle_usdce_to_pusd`."""
        res = self.wrap_idle_usdce_to_pusd(min_usd=min_usd)
        return {
            **res,
            "success": bool(res.get("wrapped")),
            "wrapped_usd": float(res.get("amount_usd") or 0.0) if res.get("wrapped") else 0.0,
        }

    def _dispatch_funder_calls(
        self,
        w3: Any,
        Web3: Any,
        pk: str,
        sig_type: int,
        funder_cs: str,
        signer_cs: str,
        call_targets: List[Tuple[str, str]],
        condition_id: str,
    ) -> Optional[str]:
        tx_lock = getattr(self, "_onchain_tx_lock", None)
        if tx_lock is None:
            tx_lock = threading.RLock()
            self._onchain_tx_lock = tx_lock
        with tx_lock:
            return self._dispatch_funder_calls_locked(
                w3, Web3, pk, sig_type, funder_cs, signer_cs, call_targets, condition_id
            )

    def _dispatch_funder_calls_locked(
        self,
        w3: Any,
        Web3: Any,
        pk: str,
        sig_type: int,
        funder_cs: str,
        signer_cs: str,
        call_targets: List[Tuple[str, str]],
        condition_id: str,
    ) -> Optional[str]:
        if sig_type == 3:
            dw_abi = [{"inputs": [], "name": "nonce", "outputs": [{"name": "", "type": "uint256"}], "stateMutability": "view", "type": "function"}]
            dw = w3.eth.contract(address=funder_cs, abi=dw_abi)
            dw_nonce = int(dw.functions.nonce().call())
            calls_payload = [{"target": tgt, "value": "0", "data": d_hex} for tgt, d_hex in call_targets]
            return self._submit_deposit_wallet_relayer_redemption(
                pk=pk, funder_cs=funder_cs, nonce=dw_nonce, calls=calls_payload, condition_id=condition_id
            )
        def _exec_seq(mk_tx):
            last_tx: Optional[str] = None
            for i_c, (tgt_cs, inner_hex) in enumerate(call_targets):
                is_appr = str(inner_hex).lower().startswith(("0x095ea7b3", "0xa22cb465"))
                try:
                    tx = mk_tx(tgt_cs, inner_hex)
                    if not tx:
                        if is_appr:
                            return None
                        continue
                    raw_h = w3.eth.send_raw_transaction(w3.eth.account.sign_transaction(tx, private_key=pk).raw_transaction).hex()
                    tx_h = raw_h if str(raw_h).startswith("0x") else f"0x{raw_h}"
                    if i_c + 1 < len(call_targets):
                        if int(w3.eth.wait_for_transaction_receipt(tx_h, timeout=45, poll_latency=1.2).get("status", 0)) != 1:
                            return None
                        if not is_appr:
                            last_tx = tx_h
                    else:
                        return tx_h
                except Exception:
                    if is_appr:
                        return None
            return last_tx

        if sig_type == 2:
            safe_abi = [
                {"inputs": [], "name": "getThreshold", "outputs": [{"name": "", "type": "uint256"}], "stateMutability": "view", "type": "function"},
                {"inputs": [], "name": "getOwners", "outputs": [{"name": "", "type": "address[]"}], "stateMutability": "view", "type": "function"},
                {"inputs": [{"name": "to", "type": "address"}, {"name": "value", "type": "uint256"}, {"name": "data", "type": "bytes"}, {"name": "operation", "type": "uint8"}, {"name": "safeTxGas", "type": "uint256"}, {"name": "baseGas", "type": "uint256"}, {"name": "gasPrice", "type": "uint256"}, {"name": "gasToken", "type": "address"}, {"name": "refundReceiver", "type": "address"}, {"name": "signatures", "type": "bytes"}], "name": "execTransaction", "outputs": [{"name": "success", "type": "bool"}], "stateMutability": "payable", "type": "function"},
            ]
            safe = w3.eth.contract(address=funder_cs, abi=safe_abi)
            try:
                owners = [Web3.to_checksum_address(o) for o in safe.functions.getOwners().call()]
                threshold_val = int(safe.functions.getThreshold().call())
            except Exception:
                self._funder_is_gnosis_safe = False
                return None
            self._funder_is_gnosis_safe = True
            if threshold_val != 1 or signer_cs not in owners:
                return None
            zero_cs = Web3.to_checksum_address("0x" + "00" * 20)
            preval_sig = b"\x00" * 12 + bytes.fromhex(signer_cs[2:].lower()) + b"\x00" * 32 + b"\x01"

            def _mk_safe_tx(tgt_cs, inner_hex):
                fn = safe.functions.execTransaction(tgt_cs, 0, bytes.fromhex(inner_hex[2:] if inner_hex.startswith("0x") else inner_hex), 0, 0, 0, 0, zero_cs, zero_cs, preval_sig)
                return fn.build_transaction({"from": signer_cs, "nonce": w3.eth.get_transaction_count(signer_cs, "pending"), "gas": 300000, "gasPrice": w3.eth.gas_price, "chainId": 137}) if fn.call({"from": signer_cs}) else None

            return _exec_seq(_mk_safe_tx)
        if sig_type == 1:
            pf_abi = [{
                "inputs": [{"components": [{"name": "typeCode", "type": "uint8"}, {"name": "to", "type": "address"}, {"name": "value", "type": "uint256"}, {"name": "data", "type": "bytes"}], "name": "calls", "type": "tuple[]"}],
                "name": "proxy",
                "outputs": [{"name": "returnValues", "type": "bytes[]"}],
                "stateMutability": "payable",
                "type": "function",
            }]
            pf = w3.eth.contract(address=Web3.to_checksum_address(self.POLY_PROXY_FACTORY), abi=pf_abi)
            tuple_calls = [(1, tgt_cs, 0, bytes.fromhex(h[2:] if h.startswith("0x") else h)) for tgt_cs, h in call_targets]
            pf.functions.proxy(tuple_calls).call({"from": signer_cs})
            tx = pf.functions.proxy(tuple_calls).build_transaction({"from": signer_cs, "nonce": w3.eth.get_transaction_count(signer_cs, "pending"), "gas": 320000, "gasPrice": w3.eth.gas_price, "chainId": 137})
            raw_h = w3.eth.send_raw_transaction(w3.eth.account.sign_transaction(tx, private_key=pk).raw_transaction).hex()
            return raw_h if str(raw_h).startswith("0x") else f"0x{raw_h}"
        return _exec_seq(lambda t, h: (w3.eth.call({"from": funder_cs, "to": t, "data": h}), {"from": funder_cs, "to": t, "value": 0, "data": h, "nonce": w3.eth.get_transaction_count(funder_cs, "pending"), "gas": 250000, "gasPrice": w3.eth.gas_price, "chainId": 137})[1])

    def attempt_onchain_complete_set_merge(
        self, condition_id: str, *, min_pairs: float = 5.0, max_pairs: Optional[float] = None, neg_risk: Optional[bool] = None
    ) -> Optional[Tuple[str, float]]:
        """Instant pre-expiry CTF mergePositions(YES+NO -> $1.00/pair pUSD/USDC.e) for C1 Complete Sets."""
        raw_sig_type = getattr(self, "signature_type", None)
        sig_type = 1 if raw_sig_type is None else int(raw_sig_type)
        if self.dry_run or not condition_id or sig_type not in (0, 1, 2, 3):
            return None
        b_key = (os.getenv("POLY_BUILDER_API_KEY") or os.getenv("BUILDER_API_KEY") or "").strip()
        if sig_type == 3 and not b_key:
            return None
        if sig_type == 2 and getattr(self, "_funder_is_gnosis_safe", None) is False:
            return None
        pk = (os.getenv("POLYGON_PRIVATE_KEY") or self.private_key or "").strip()
        if not pk or not self.funder_address:
            return None
        try:
            from web3 import Web3
            from src.polymarket_research.riskless_machine_gun_engine import get_fast_polygon_web3
            w3 = get_fast_polygon_web3(timeout=5.0)
            funder_cs = Web3.to_checksum_address(self.funder_address)
            signer_cs = Web3.to_checksum_address(w3.eth.account.from_key(pk).address)
            if sig_type in (0, 1, 2):
                gas_payer_cs = funder_cs if sig_type == 0 else signer_cs
                if w3.eth.get_balance(gas_payer_cs) < int(0.05 * 1e18):
                    return None
            cond_bytes = bytes.fromhex(condition_id.lower().replace("0x", "").rjust(64, "0"))
            min_raw = max(1, int(math.floor(float(min_pairs) * 1e6)))
            # Cap merge at this box's own pairs so concurrent boxes on the same condition aren't burned/over-booked.
            max_raw = max(min_raw, int(math.floor(float(max_pairs) * 1e6))) if max_pairs else None
            ctf_abi = [
                {"inputs": [{"name": "collateralToken", "type": "address"}, {"name": "parentCollectionId", "type": "bytes32"}, {"name": "conditionId", "type": "bytes32"}, {"name": "partition", "type": "uint256[]"}, {"name": "amount", "type": "uint256"}], "name": "mergePositions", "outputs": [], "stateMutability": "nonpayable", "type": "function"},
                {"inputs": [{"name": "parentCollectionId", "type": "bytes32"}, {"name": "conditionId", "type": "bytes32"}, {"name": "indexSet", "type": "uint256"}], "name": "getCollectionId", "outputs": [{"name": "", "type": "bytes32"}], "stateMutability": "view", "type": "function"},
                {"inputs": [{"name": "collateralToken", "type": "address"}, {"name": "collectionId", "type": "bytes32"}], "name": "getPositionId", "outputs": [{"name": "", "type": "uint256"}], "stateMutability": "pure", "type": "function"},
                {"inputs": [{"name": "owner", "type": "address"}, {"name": "id", "type": "uint256"}], "name": "balanceOf", "outputs": [{"name": "", "type": "uint256"}], "stateMutability": "view", "type": "function"},
                {"inputs": [{"name": "account", "type": "address"}, {"name": "operator", "type": "address"}], "name": "isApprovedForAll", "outputs": [{"name": "", "type": "bool"}], "stateMutability": "view", "type": "function"},
            ]
            nr_abi = [{"inputs": [{"name": "_conditionId", "type": "bytes32"}, {"name": "_amount", "type": "uint256"}], "name": "mergePositions", "outputs": [], "stateMutability": "nonpayable", "type": "function"}]
            ctf_cs = Web3.to_checksum_address(self.CTF_ADDRESS)
            ctf = w3.eth.contract(address=ctf_cs, abi=ctf_abi)
            nr_cs = Web3.to_checksum_address(self.NEG_RISK_ADAPTER_ADDRESS)
            nr_v2_cs = Web3.to_checksum_address(self.NEG_RISK_ADAPTER_V2_ADDRESS)
            nr_contract = w3.eth.contract(address=nr_cs, abi=nr_abi)
            merge_targets: List[Tuple[str, str]] = []
            merged_raw = 0
            used_v1_usdce = False
            if neg_risk is not False:
                try:
                    wcol_cs = Web3.to_checksum_address(self.NEG_RISK_WRAPPED_COLLATERAL)
                    b_yes = int(ctf.functions.balanceOf(funder_cs, ctf.functions.getPositionId(wcol_cs, ctf.functions.getCollectionId(b"\x00" * 32, cond_bytes, 1).call()).call()).call())
                    b_no = int(ctf.functions.balanceOf(funder_cs, ctf.functions.getPositionId(wcol_cs, ctf.functions.getCollectionId(b"\x00" * 32, cond_bytes, 2).call()).call()).call())
                    m_nr = min(b_yes, b_no) if max_raw is None else min(b_yes, b_no, max_raw)
                    if m_nr >= min_raw:
                        appr_nr_v2 = bool(ctf.functions.isApprovedForAll(funder_cs, nr_v2_cs).call())
                        if not appr_nr_v2 and sig_type == 3:
                            merge_targets.append((ctf_cs, f"0xa22cb465{nr_v2_cs[2:].lower().rjust(64, '0')}{'1'.rjust(64, '0')}"))
                            appr_nr_v2 = True
                        nr_tgt = nr_v2_cs if appr_nr_v2 else nr_cs
                        if not appr_nr_v2:
                            used_v1_usdce = True
                        nr_hex = nr_contract.encode_abi("mergePositions", args=[cond_bytes, m_nr]) if hasattr(nr_contract, "encode_abi") else nr_contract.encodeABI(fn_name="mergePositions", args=[cond_bytes, m_nr])
                        merge_targets.append((nr_tgt, nr_hex))
                        merged_raw += m_nr
                except Exception:
                    pass
            if neg_risk is not True and not merge_targets:
                pusd_cs = Web3.to_checksum_address(self.PUSD_ADDRESS)
                v2_ctf_cs = Web3.to_checksum_address(self.CTF_ADAPTER_V2_ADDRESS)
                for col_hex in (self.PUSD_ADDRESS, self.USDC_E_ADDRESS):
                    try:
                        col_cs = Web3.to_checksum_address(col_hex)
                        b_yes = int(ctf.functions.balanceOf(funder_cs, ctf.functions.getPositionId(col_cs, ctf.functions.getCollectionId(b"\x00" * 32, cond_bytes, 1).call()).call()).call())
                        b_no = int(ctf.functions.balanceOf(funder_cs, ctf.functions.getPositionId(col_cs, ctf.functions.getCollectionId(b"\x00" * 32, cond_bytes, 2).call()).call()).call())
                        m_std = min(b_yes, b_no) if max_raw is None else min(b_yes, b_no, max_raw)
                        if m_std >= min_raw:
                            appr_v2 = col_cs != pusd_cs and bool(ctf.functions.isApprovedForAll(funder_cs, v2_ctf_cs).call())
                            if col_cs != pusd_cs and not appr_v2 and sig_type == 3:
                                merge_targets.append((ctf_cs, f"0xa22cb465{v2_ctf_cs[2:].lower().rjust(64, '0')}{'1'.rjust(64, '0')}"))
                                appr_v2 = True
                            m_col = pusd_cs if appr_v2 else col_cs
                            m_tgt = v2_ctf_cs if appr_v2 else ctf_cs
                            if m_col != pusd_cs:
                                used_v1_usdce = True
                            ctf_hex = ctf.encode_abi("mergePositions", args=[m_col, b"\x00" * 32, cond_bytes, [1, 2], m_std]) if hasattr(ctf, "encode_abi") else ctf.encodeABI(fn_name="mergePositions", args=[m_col, b"\x00" * 32, cond_bytes, [1, 2], m_std])
                            merge_targets.append((m_tgt, ctf_hex))
                            merged_raw += m_std
                            break
                    except Exception:
                        continue
            if not merge_targets or merged_raw < min_raw:
                return None
            tx_h = self._dispatch_funder_calls(w3, Web3, pk, sig_type, funder_cs, signer_cs, merge_targets, condition_id)
            if tx_h:
                self.invalidate_collateral_cache()
                # Only report success once the merge is mined with status=1; callers close both legs on success.
                try:
                    rc = w3.eth.wait_for_transaction_receipt(tx_h, timeout=60, poll_latency=1.5)
                    if int(rc.get("status", 0)) != 1:
                        logger.warning(f"[MERGE] mergePositions tx {tx_h} reverted for {condition_id}; legs remain open.")
                        return None
                except Exception as rc_err:
                    logger.warning(f"[MERGE] mergePositions tx {tx_h} unconfirmed for {condition_id} ({rc_err}); legs remain open.")
                    return None
                if used_v1_usdce:
                    self.wrap_idle_usdce_to_pusd(min_usd=0.50)
                self.sync_clob_collateral_allowance()
                return tx_h, round(merged_raw / 1e6, 6)
            return None
        except Exception as e:
            logger.debug(f"On-chain mergePositions skipped for {condition_id}: {e}")
            return None

    def attempt_onchain_batch_complete_set_merges(
        self, merge_specs: List[Dict[str, Any]]
    ) -> Optional[Tuple[str, Dict[str, float]]]:
        """
        Packs multiple ready `C1` `mergePositions` calls into a SINGLE Relayer V2 / Proxy `Call[]`
        batch transaction (`batch_merge:{count}:{first_cond}`), consuming only 1 Relayer quota unit
        and 1 Polygon block confirmation (`~2.2s`) across up to 8 concurrent complete-set boxes.
        Each item in `merge_specs`: `{"key": str, "condition_id": str, "min_pairs": float, "max_pairs": float, "neg_risk": Optional[bool]}`.
        Returns `(tx_hash, {spec_key: merged_pairs_float})` strictly after mined `status == 1`.
        """
        raw_sig_type = getattr(self, "signature_type", None)
        sig_type = 1 if raw_sig_type is None else int(raw_sig_type)
        if self.dry_run or not merge_specs or sig_type not in (0, 1, 2, 3):
            return None
        b_key = (os.getenv("POLY_BUILDER_API_KEY") or os.getenv("BUILDER_API_KEY") or "").strip()
        if sig_type == 3 and not b_key:
            return None
        if sig_type == 2 and getattr(self, "_funder_is_gnosis_safe", None) is False:
            return None
        pk = (os.getenv("POLYGON_PRIVATE_KEY") or self.private_key or "").strip()
        if not pk or not self.funder_address:
            return None
        try:
            from web3 import Web3
            from src.polymarket_research.riskless_machine_gun_engine import get_fast_polygon_web3
            w3 = get_fast_polygon_web3(timeout=5.0)
            funder_cs = Web3.to_checksum_address(self.funder_address)
            signer_cs = Web3.to_checksum_address(w3.eth.account.from_key(pk).address)
            if sig_type in (0, 1, 2):
                gas_payer_cs = funder_cs if sig_type == 0 else signer_cs
                if w3.eth.get_balance(gas_payer_cs) < int(0.05 * 1e18):
                    return None
            ctf_abi = [
                {"inputs": [{"name": "collateralToken", "type": "address"}, {"name": "parentCollectionId", "type": "bytes32"}, {"name": "conditionId", "type": "bytes32"}, {"name": "partition", "type": "uint256[]"}, {"name": "amount", "type": "uint256"}], "name": "mergePositions", "outputs": [], "stateMutability": "nonpayable", "type": "function"},
                {"inputs": [{"name": "parentCollectionId", "type": "bytes32"}, {"name": "conditionId", "type": "bytes32"}, {"name": "indexSet", "type": "uint256"}], "name": "getCollectionId", "outputs": [{"name": "", "type": "bytes32"}], "stateMutability": "view", "type": "function"},
                {"inputs": [{"name": "collateralToken", "type": "address"}, {"name": "collectionId", "type": "bytes32"}], "name": "getPositionId", "outputs": [{"name": "", "type": "uint256"}], "stateMutability": "pure", "type": "function"},
                {"inputs": [{"name": "owner", "type": "address"}, {"name": "id", "type": "uint256"}], "name": "balanceOf", "outputs": [{"name": "", "type": "uint256"}], "stateMutability": "view", "type": "function"},
                {"inputs": [{"name": "account", "type": "address"}, {"name": "operator", "type": "address"}], "name": "isApprovedForAll", "outputs": [{"name": "", "type": "bool"}], "stateMutability": "view", "type": "function"},
            ]
            nr_abi = [{"inputs": [{"name": "_conditionId", "type": "bytes32"}, {"name": "_amount", "type": "uint256"}], "name": "mergePositions", "outputs": [], "stateMutability": "nonpayable", "type": "function"}]
            ctf_cs = Web3.to_checksum_address(self.CTF_ADDRESS)
            ctf = w3.eth.contract(address=ctf_cs, abi=ctf_abi)
            nr_cs = Web3.to_checksum_address(self.NEG_RISK_ADAPTER_ADDRESS)
            nr_v2_cs = Web3.to_checksum_address(self.NEG_RISK_ADAPTER_V2_ADDRESS)
            nr_contract = w3.eth.contract(address=nr_cs, abi=nr_abi)
            pusd_cs = Web3.to_checksum_address(self.PUSD_ADDRESS)
            v2_ctf_cs = Web3.to_checksum_address(self.CTF_ADAPTER_V2_ADDRESS)
            wcol_cs = Web3.to_checksum_address(self.NEG_RISK_WRAPPED_COLLATERAL)

            batch_calls: List[Tuple[str, str]] = []
            merged_by_key: Dict[str, float] = {}
            added_v2_approval = False
            added_nr_v2_approval = False
            used_v1_usdce = False
            consumed_by_cond: Dict[str, int] = {}

            for spec in merge_specs[:8]:
                cid = str(spec.get("condition_id") or "").strip()
                s_key = str(spec.get("key") or cid)
                if not cid:
                    continue
                cond_bytes = bytes.fromhex(cid.lower().replace("0x", "").rjust(64, "0"))
                min_raw = max(1, int(math.floor(float(spec.get("min_pairs") or 1.0) * 1e6)))
                max_p = spec.get("max_pairs")
                max_raw = max(min_raw, int(math.floor(float(max_p) * 1e6))) if max_p else None
                nr_flag = spec.get("neg_risk")
                already_used = consumed_by_cond.get(cid.lower(), 0)
                matched_spec = False

                if nr_flag is not False:
                    try:
                        b_yes = max(0, int(ctf.functions.balanceOf(funder_cs, ctf.functions.getPositionId(wcol_cs, ctf.functions.getCollectionId(b"\x00" * 32, cond_bytes, 1).call()).call()).call()) - already_used)
                        b_no = max(0, int(ctf.functions.balanceOf(funder_cs, ctf.functions.getPositionId(wcol_cs, ctf.functions.getCollectionId(b"\x00" * 32, cond_bytes, 2).call()).call()).call()) - already_used)
                        m_nr = min(b_yes, b_no) if max_raw is None else min(b_yes, b_no, max_raw)
                        if m_nr >= min_raw:
                            appr_nr_v2 = added_nr_v2_approval or bool(ctf.functions.isApprovedForAll(funder_cs, nr_v2_cs).call())
                            if not appr_nr_v2 and sig_type == 3:
                                batch_calls.append((ctf_cs, f"0xa22cb465{nr_v2_cs[2:].lower().rjust(64, '0')}{'1'.rjust(64, '0')}"))
                                appr_nr_v2 = True
                                added_nr_v2_approval = True
                            nr_tgt = nr_v2_cs if appr_nr_v2 else nr_cs
                            if not appr_nr_v2:
                                used_v1_usdce = True
                            nr_hex = nr_contract.encode_abi("mergePositions", args=[cond_bytes, m_nr]) if hasattr(nr_contract, "encode_abi") else nr_contract.encodeABI(fn_name="mergePositions", args=[cond_bytes, m_nr])
                            batch_calls.append((nr_tgt, nr_hex))
                            merged_by_key[s_key] = round(m_nr / 1e6, 6)
                            consumed_by_cond[cid.lower()] = already_used + m_nr
                            matched_spec = True
                    except Exception:
                        pass

                if nr_flag is not True and not matched_spec:
                    for col_hex in (self.PUSD_ADDRESS, self.USDC_E_ADDRESS):
                        try:
                            col_cs = Web3.to_checksum_address(col_hex)
                            b_yes = max(0, int(ctf.functions.balanceOf(funder_cs, ctf.functions.getPositionId(col_cs, ctf.functions.getCollectionId(b"\x00" * 32, cond_bytes, 1).call()).call()).call()) - already_used)
                            b_no = max(0, int(ctf.functions.balanceOf(funder_cs, ctf.functions.getPositionId(col_cs, ctf.functions.getCollectionId(b"\x00" * 32, cond_bytes, 2).call()).call()).call()) - already_used)
                            m_std = min(b_yes, b_no) if max_raw is None else min(b_yes, b_no, max_raw)
                            if m_std >= min_raw:
                                appr_v2 = col_cs != pusd_cs and (added_v2_approval or bool(ctf.functions.isApprovedForAll(funder_cs, v2_ctf_cs).call()))
                                if col_cs != pusd_cs and not appr_v2 and sig_type == 3:
                                    batch_calls.append((ctf_cs, f"0xa22cb465{v2_ctf_cs[2:].lower().rjust(64, '0')}{'1'.rjust(64, '0')}"))
                                    appr_v2 = True
                                    added_v2_approval = True
                                m_col = pusd_cs if appr_v2 else col_cs
                                m_tgt = v2_ctf_cs if appr_v2 else ctf_cs
                                if m_col != pusd_cs:
                                    used_v1_usdce = True
                                ctf_hex = ctf.encode_abi("mergePositions", args=[m_col, b"\x00" * 32, cond_bytes, [1, 2], m_std]) if hasattr(ctf, "encode_abi") else ctf.encodeABI(fn_name="mergePositions", args=[m_col, b"\x00" * 32, cond_bytes, [1, 2], m_std])
                                batch_calls.append((m_tgt, ctf_hex))
                                merged_by_key[s_key] = round(m_std / 1e6, 6)
                                consumed_by_cond[cid.lower()] = already_used + m_std
                                break
                        except Exception:
                            continue

            if not batch_calls or not merged_by_key:
                return None
            op_tag = f"batch_merge:{len(merged_by_key)}:{next(iter(merged_by_key))[:18]}"
            tx_h = self._dispatch_funder_calls(w3, Web3, pk, sig_type, funder_cs, signer_cs, batch_calls, op_tag)
            if not tx_h:
                return None
            self.invalidate_collateral_cache()
            try:
                rc = w3.eth.wait_for_transaction_receipt(tx_h, timeout=60, poll_latency=1.5)
                if int(rc.get("status", 0)) != 1:
                    logger.warning(f"[BATCH-MERGE] tx {tx_h} reverted ({op_tag}); legs remain open.")
                    return None
            except Exception as rc_err:
                logger.warning(f"[BATCH-MERGE] tx {tx_h} unconfirmed ({op_tag}: {rc_err}); legs remain open.")
                return None
            if used_v1_usdce:
                self.wrap_idle_usdce_to_pusd(min_usd=0.50)
            self.sync_clob_collateral_allowance()
            return tx_h, merged_by_key
        except Exception as e:
            logger.debug(f"On-chain batch mergePositions skipped: {e}")
            return None

    @classmethod
    def encode_negrisk_convert_positions_call(
        cls,
        market_id: str,
        question_indices: List[int],
        shares: float,
        *,
        adapter_address: Optional[str] = None,
    ) -> Dict[str, str]:
        """ABI-encodes NegRiskAdapter.convertPositions(bytes32 _marketId, uint256 _indexSet, uint256 _amount)."""
        m_hex = str(market_id or "").strip().lower().replace("0x", "")
        if len(m_hex) != 64 or any(c not in "0123456789abcdef" for c in m_hex):
            raise ValueError(f"Invalid 32-byte negRiskMarketID: {market_id!r}")
        idxs = sorted({int(i) for i in (question_indices or [])})
        if not idxs or idxs[0] < 0 or idxs[-1] >= 256:
            raise ValueError(f"Invalid NegRisk question_indices: {question_indices!r}")
        amt_raw = int(math.floor(float(shares) * 1e6))
        if amt_raw <= 0:
            raise ValueError(f"Invalid convertPositions shares: {shares!r}")
        idx_mask = 0
        for i in idxs:
            idx_mask |= 1 << i
        target_addr = str(adapter_address or cls.NEG_RISK_ADAPTER_ADDRESS)
        return {
            "target": target_addr,
            "value": "0",
            "data": f"0xc64748c4{m_hex}{idx_mask:064x}{amt_raw:064x}",
            "index_set": hex(idx_mask),
            "amount_raw": str(amt_raw),
        }

    def attempt_negrisk_convert_positions(
        self,
        market_id: str,
        question_indices: List[int],
        shares: float,
        *,
        prefer_v2_pusd_adapter: bool = True,
    ) -> Dict[str, Any]:
        """
        Submits NegRiskAdapter.convertPositions (`0xc64748c4`) via Relayer V2 (sig_type=3) / Safe / Proxy / EOA.
        Automatically prefers Polymarket V2 `NEG_RISK_ADAPTER_V2_ADDRESS` (`0xadA2...`) when CTF operator approval
        is active on `funder_address`, converting `m` NO tokens into `(m - 1)` V2 `pUSD` (`0xC011...`) + complement YES.
        """
        default_target = self.NEG_RISK_ADAPTER_V2_ADDRESS if prefer_v2_pusd_adapter else self.NEG_RISK_ADAPTER_ADDRESS
        call = self.encode_negrisk_convert_positions_call(
            market_id, question_indices, shares, adapter_address=default_target
        )
        if self.dry_run:
            return {
                "success": True,
                "dry_run": True,
                "tx_hash": f"0xdry_nr_conv_{int(time.time())}",
                "adapter_used": call["target"],
                "call": call,
            }
        sig_type = 1 if getattr(self, "signature_type", None) is None else int(self.signature_type)
        b_key = (os.getenv("POLY_BUILDER_API_KEY") or os.getenv("BUILDER_API_KEY") or "").strip()
        if sig_type == 3 and not b_key:
            return {"success": False, "tx_hash": None, "error": "MISSING_BUILDER_API_KEY_FOR_RELAYER_V2", "call": call}
        pk = (os.getenv("POLYGON_PRIVATE_KEY") or self.private_key or "").strip()
        if sig_type not in (0, 1, 2, 3) or not pk or not self.funder_address:
            return {"success": False, "tx_hash": None, "error": "MISSING_CREDENTIALS_OR_UNSUPPORTED_SIG_TYPE", "call": call}
        try:
            from web3 import Web3
            from src.polymarket_research.riskless_machine_gun_engine import get_fast_polygon_web3
            w3 = get_fast_polygon_web3(timeout=5.0)
            funder_cs = Web3.to_checksum_address(self.funder_address)
            signer_cs = Web3.to_checksum_address(w3.eth.account.from_key(pk).address)
            if sig_type in (0, 1, 2) and w3.eth.get_balance(funder_cs if sig_type == 0 else signer_cs) < int(0.05 * 1e18):
                return {"success": False, "tx_hash": None, "error": "INSUFFICIENT_EOA_POL_GAS", "call": call}

            chosen_adapter = self.NEG_RISK_ADAPTER_ADDRESS
            if prefer_v2_pusd_adapter:
                try:
                    ctf_op = w3.eth.contract(
                        address=Web3.to_checksum_address(self.CTF_ADDRESS),
                        abi=[{"constant": True, "inputs": [{"name": "account", "type": "address"}, {"name": "operator", "type": "address"}], "name": "isApprovedForAll", "outputs": [{"name": "", "type": "bool"}], "type": "function"}],
                    )
                    v2_cs = Web3.to_checksum_address(self.NEG_RISK_ADAPTER_V2_ADDRESS)
                    if bool(ctf_op.functions.isApprovedForAll(funder_cs, v2_cs).call()):
                        chosen_adapter = self.NEG_RISK_ADAPTER_V2_ADDRESS
                except Exception:
                    chosen_adapter = self.NEG_RISK_ADAPTER_V2_ADDRESS
            call = self.encode_negrisk_convert_positions_call(
                market_id, question_indices, shares, adapter_address=chosen_adapter
            )
            tx_h = self._dispatch_funder_calls(
                w3, Web3, pk, sig_type, funder_cs, signer_cs,
                [(Web3.to_checksum_address(call["target"]), call["data"])], f"nrconv:{market_id.lower()}",
            )
            if tx_h:
                rc = w3.eth.wait_for_transaction_receipt(tx_h, timeout=60, poll_latency=1.5)
                if int(rc.get("status", 0)) == 1:
                    self.invalidate_collateral_cache()
                    try:
                        if self.client is not None and BalanceAllowanceParams is not None and AssetType is not None:
                            self.client.update_balance_allowance(
                                BalanceAllowanceParams(asset_type=AssetType.COLLATERAL, signature_type=sig_type)
                            )
                    except Exception:
                        pass
                    return {
                        "success": True,
                        "tx_hash": tx_h,
                        "adapter_used": chosen_adapter,
                        "pusd_wrapped": chosen_adapter.lower() == self.NEG_RISK_ADAPTER_V2_ADDRESS.lower(),
                        "call": call,
                    }
        except Exception as exc:
            logger.warning(f"[NR_CONVERT] convertPositions failed for {market_id}: {exc}")
            return {"success": False, "tx_hash": None, "error": str(exc), "call": call}
        return {"success": False, "tx_hash": None, "error": "CONVERT_DISPATCH_FAILED", "call": call}

