def _extract_weather_icao_key(cand: Mapping[str, Any]) -> str:
    """
    Extracts canonical `EVTWX:<ICAO>:<12h_bucket>` across ALL sleeves unconditionally so weather
    markets entering via `BOND1`, `UMA_READY1`, `MKR_LOCK1`, `NR0`, `MULTI_LEG_BUNDLE`, or `W_PRUNE1`
    can NEVER bypass correlated weather-station/day concentration accounting via sleeve-name or asset aliases.
    """
    exp_i = int(float(cand.get("expiry_ts") or cand.get("leg_a_expiry_ts") or cand.get("candle_expiry_ts") or 0.0))
    sl_u = str(cand.get("sleeve_source") or cand.get("sleeve") or "").strip().upper()
    ast_s = str(cand.get("asset") or "").strip().upper()
    non_wx_tickers = {"GOLD", "SILV", "XAUU", "XAGU", "SP50", "NDX1", "CLIN", "HYPE", "DOGE", "USDT", "USDC"}
    try:
        from src.polymarket_research.weather_metar_engine import STATION_CATALOG as _WX_CAT, _SERIES_TO_ICAO as _WX_SERIES
    except Exception:
        _WX_CAT, _WX_SERIES = {}, {}
    known_icaos = set(_WX_CAT.keys()) | set(_WX_SERIES.values()) | set(WUNDERGROUND_INTL_INTEGER_STATIONS) | {"HKO"}

    m_any = _ICAO_ANY_SUFFIX_RE.match(ast_s)
    if m_any:
        st_c = m_any.group(1)
        if st_c in known_icaos and st_c not in non_wx_tickers:
            return f"EVTWX:{st_c}:{exp_i // 43200}"
    m_ic = _ICAO_SUFFIX_RE.match(ast_s)
    if m_ic and m_ic.group(1) not in non_wx_tickers:
        if m_ic.group(1) in known_icaos or sl_u.startswith(("W_PRUNE", "W1_", "W_SOLAR")) or "_" in ast_s or len(ast_s) == 4:
            return f"EVTWX:{m_ic.group(1)}:{exp_i // 43200}"

    blob_parts = [
        str(cand.get(f) or "")
        for f in ("event_slug", "slug", "market_slug", "series_slug", "question", "title", "leg_a_label", "trade_id", "box_id", "event_id")
    ]
    blob = " | ".join(p for p in blob_parts if p)
    if not blob:
        return ""
    blob_low = blob.lower()
    for ser_slug, ser_icao in _WX_SERIES.items():
        if ser_slug in blob_low:
            return f"EVTWX:{ser_icao}:{exp_i // 43200}"
    for icao_cand in known_icaos:
        if len(icao_cand) >= 3 and re.search(rf"(?:^|[^A-Z0-9]){re.escape(icao_cand)}(?:[^A-Z0-9]|$)", blob.upper()):
            return f"EVTWX:{icao_cand}:{exp_i // 43200}"
    if sl_u.startswith(("W_PRUNE", "W1_", "W_SOLAR")) or "WEATHER" in sl_u or "METAR" in sl_u or _WEATHER_CONTEXT_RE.search(blob):
        for pat_city, city_icao in _WEATHER_CITY_ALIASES:
            if pat_city.search(blob):
                return f"EVTWX:{city_icao}:{exp_i // 43200}"
    return ""


def extract_gamma_parent_event_id(m: Optional[Mapping[str, Any]]) -> str:
    """Extracts a canonical parent Gamma event ID/slug from a market dict so multi-prop games share one event slot."""
    if not isinstance(m, Mapping):
        return ""
    for k in ("_parent_event_id", "event_id", "parent_event_id", "eventSlug", "event_slug", "negRiskMarketID"):
        v = str(m.get(k) or "").strip()
        if v:
            return v
    evs = m.get("events")
    if isinstance(evs, list) and evs and isinstance(evs[0], Mapping):
        for k in ("id", "slug", "ticker"):
            v = str(evs[0].get(k) or "").strip()
            if v:
                return v
    slug_s = str(m.get("slug") or "").strip()
    if slug_s:
        m_sl = _SLUG_MKT_SUFFIX_RE.sub("", slug_s)
        if m_sl and m_sl != slug_s:
            return m_sl
    return ""


def extract_sll_event_group_key(cand: Optional[Mapping[str, Any]]) -> str:
    """Extracts a canonical parent-event key so multi-bracket slates (e.g. 16 Exact Score brackets or METAR ladders) share slot & concentration guards."""
    if not isinstance(cand, Mapping):
        return ""
    egk = str(cand.get("event_group_key") or "").strip()
    if egk:
        egk_body = egk[4:] if egk.upper().startswith("EVT:") else egk
        if not egk_body.upper().startswith(_SYNTH_EVENT_ID_PREFIXES):
            return egk
    for k in ("event_id", "parent_event_id", "neg_risk_market_id", "event_slug"):
        v = str(cand.get(k) or "").strip()
        if not v:
            continue
        if v.upper().startswith(_SYNTH_EVENT_ID_PREFIXES):
            v_clean = _UNWRESID_SFX_RE.sub("", v)
            m_emb = _EMBEDDED_EVT_RE.match(v_clean)
            if m_emb:
                return f"EVT:{m_emb.group(1)}"
            continue
        return f"EVT:{v}"
    for dk_field in ("dedupe_key", "pair_dedupe_key", "box_id", "trade_id"):
        dk_v = str(cand.get(dk_field) or "").strip()
        if dk_v:
            dk_clean = _UNWRESID_SFX_RE.sub("", dk_v)
            m_dk = _DEDUPE_EVT_RE.match(dk_clean) or _EMBEDDED_EVT_RE.match(dk_clean)
            if m_dk:
                return f"EVT:{m_dk.group(1)}"
    q_txt = str(cand.get("question") or "").strip()
    exp_i = int(float(cand.get("expiry_ts") or cand.get("leg_a_expiry_ts") or cand.get("candle_expiry_ts") or 0.0))
    if q_txt:
        q_clean = _BRACKET_PAREN_RE.sub(" ", q_txt)
        m_vs = _VS_Q_RE.search(q_clean)
        if m_vs:
            t1 = _VS_T1_PFX_RE.sub("", m_vs.group(1)).strip(" :-_|")
            t2 = m_vs.group(2).strip(" :-_|")
            if len(t1) >= 2 and len(t2) >= 2:
                pair_k = " VS ".join(sorted((t1.upper(), t2.upper())))
                return f"EVTMATCH:{pair_k}:{exp_i // 7200}"
    wx_k = _extract_weather_icao_key(cand)
    if wx_k:
        return wx_k
    reg = str(cand.get("regime") or "").strip()
    lbl = str(cand.get("leg_a_label") or cand.get("title") or "").strip()
    ast_s = str(cand.get("asset") or "").strip().upper()
    if lbl and lbl.lower() not in {"lock", "bundle", "resid", "clinch_ws_snipe"}:
        base_lbl = _BRACKET_PAREN_RE.sub(" ", lbl)
        base_lbl = _LBL_PFX_RE.sub("", base_lbl)
        base_lbl = _LBL_GAME_RE.sub(" ", base_lbl)
        base_lbl = _LBL_SFX_RE.sub("", base_lbl)
        base_lbl = _LBL_SCORE_RE.sub(" vs ", base_lbl)
        base_lbl = _LBL_TAIL_NUM_RE.sub("", base_lbl)
        base_lbl = _WHITESPACE_RUN_RE.sub(" ", base_lbl).strip(" :-_|")
        m_lbl_vs = _LBL_VS_RE.search(base_lbl)
        if m_lbl_vs:
            lt1 = _LBL_SPORT_PFX_RE.sub("", m_lbl_vs.group(1)).strip(" :-_|")
            lt2 = _LBL_YESNO_SFX_RE.sub("", m_lbl_vs.group(2)).strip(" :-_|")
            if len(lt1) >= 2 and len(lt2) >= 2:
                pair_lk = " VS ".join(sorted((lt1.upper(), lt2.upper())))
                return f"EVTMATCH:{pair_lk}:{exp_i // 7200}"
        if len(base_lbl) >= 6:
            return f"EVTLBL:{ast_s}:{base_lbl[:40].upper()}:{exp_i // 900}"
    if ast_s and exp_i > 0 and ("EXACT_SCORE" in reg.upper() or ast_s.endswith("_K")):
        return f"EVTAST:{ast_s}:{exp_i // 900}"
    mid = str(cand.get("leg_a_market_id") or cand.get("market_id") or "").strip()
    return f"MKT:{mid}" if mid else ""


def extract_canonical_event_keys(
    cand: Optional[Mapping[str, Any]],
    market_ids: Optional[Sequence[str]] = None,
) -> set[str]:
    """
    Returns ALL canonical event/market/condition/weather aliases simultaneously (`EVT:*`, `MKT:*`,
    `COND:*`, `EVTMATCH:*`, `EVTLBL:*`, `EVTWX:*`, `WSTAT:*`, `WXSTATION:*`) so follow-on sleeves
    entering the same underlying market/condition/event without `event_id` can NEVER bypass the
    `15%` reconciled NAV concentration cap via single-key mismatch.
    """
    if not isinstance(cand, Mapping):
        return set()
    out: set[str] = set()
    pk = extract_sll_event_group_key(cand)
    if pk:
        out.add(pk)

    egk = str(cand.get("event_group_key") or "").strip()
    if egk:
        egk_body = egk[4:] if egk.upper().startswith("EVT:") else egk
        if not egk_body.upper().startswith(_SYNTH_EVENT_ID_PREFIXES):
            out.add(egk if ":" in egk else f"EVT:{egk}")
        else:
            egk_clean = _UNWRESID_SFX_RE.sub("", egk_body)
            m_egk = _EMBEDDED_EVT_RE.match(egk_clean)
            if m_egk:
                out.add(f"EVT:{m_egk.group(1)}")

    for k in ("event_id", "parent_event_id", "neg_risk_market_id", "event_slug"):
        v = str(cand.get(k) or "").strip()
        if not v:
            continue
        if v.upper().startswith(_SYNTH_EVENT_ID_PREFIXES):
            v_clean = _UNWRESID_SFX_RE.sub("", v)
            m_emb = _EMBEDDED_EVT_RE.match(v_clean)
            if m_emb:
                out.add(f"EVT:{m_emb.group(1)}")
            continue
        out.add(v if v.upper().startswith("EVT:") else f"EVT:{v}")

    for dk_field in ("dedupe_key", "pair_dedupe_key", "box_id", "trade_id"):
        dk_v = str(cand.get(dk_field) or "").strip()
        if dk_v:
            dk_clean = _UNWRESID_SFX_RE.sub("", dk_v)
            m_dk = _DEDUPE_EVT_RE.match(dk_clean) or _EMBEDDED_EVT_RE.match(dk_clean)
            if m_dk:
                out.add(f"EVT:{m_dk.group(1)}")

    for m_raw in (
        *(market_ids or ()),
        cand.get("market_id"),
        cand.get("leg_a_market_id"),
        cand.get("leg_b_market_id"),
    ):
        ms = str(m_raw or "").strip()
        if ms:
            out.add(f"MKT:{ms}")
    for seq_fld in ("legs", "no_legs"):
        seq_v = cand.get(seq_fld)
        if isinstance(seq_v, Sequence) and not isinstance(seq_v, (str, bytes)):
            for lg in seq_v:
                if isinstance(lg, Mapping):
                    lms = str(lg.get("market_id") or "").strip()
                    if lms:
                        out.add(f"MKT:{lms}")
                    lcs = str(lg.get("condition_id") or "").strip().lower()
                    if lcs:
                        out.add(f"COND:{lcs}")

    for c_raw in (
        cand.get("condition_id"),
        cand.get("leg_a_condition_id"),
        cand.get("leg_b_condition_id"),
    ):
        cs = str(c_raw or "").strip().lower()
        if cs:
            out.add(f"COND:{cs}")

    exp_i = int(float(cand.get("expiry_ts") or cand.get("leg_a_expiry_ts") or cand.get("candle_expiry_ts") or 0.0))
    q_txt = str(cand.get("question") or "").strip()
    if q_txt:
        q_clean = _BRACKET_PAREN_RE.sub(" ", q_txt)
        m_vs = _VS_Q_RE.search(q_clean)
        if m_vs:
            t1 = _VS_T1_PFX_RE.sub("", m_vs.group(1)).strip(" :-_|")
            t2 = m_vs.group(2).strip(" :-_|")
            if len(t1) >= 2 and len(t2) >= 2:
                pair_k = " VS ".join(sorted((t1.upper(), t2.upper())))
                out.add(f"EVTMATCH:{pair_k}:{exp_i // 7200}")

    lbl = str(cand.get("leg_a_label") or cand.get("title") or "").strip()
    ast_s = str(cand.get("asset") or "").strip().upper()
    if lbl and lbl.lower() not in {"lock", "bundle", "resid", "clinch_ws_snipe"}:
        base_lbl = _BRACKET_PAREN_RE.sub(" ", lbl)
        base_lbl = _LBL_PFX_RE.sub("", base_lbl)
        base_lbl = _LBL_GAME_RE.sub(" ", base_lbl)
        base_lbl = _LBL_SFX_RE.sub("", base_lbl)
        base_lbl = _LBL_SCORE_RE.sub(" vs ", base_lbl)
        base_lbl = _LBL_TAIL_NUM_RE.sub("", base_lbl)
        base_lbl = _WHITESPACE_RUN_RE.sub(" ", base_lbl).strip(" :-_|")
        m_lbl_vs = _LBL_VS_RE.search(base_lbl)
        if m_lbl_vs:
            lt1 = _LBL_SPORT_PFX_RE.sub("", m_lbl_vs.group(1)).strip(" :-_|")
            lt2 = _LBL_YESNO_SFX_RE.sub("", m_lbl_vs.group(2)).strip(" :-_|")
            if len(lt1) >= 2 and len(lt2) >= 2:
                pair_lk = " VS ".join(sorted((lt1.upper(), lt2.upper())))
                out.add(f"EVTMATCH:{pair_lk}:{exp_i // 7200}")

    wx_k = _extract_weather_icao_key(cand)
    if wx_k:
        out.add(wx_k)
        parts_wx = wx_k.split(":")
        if len(parts_wx) >= 2 and parts_wx[1]:
            out.add(f"WXSTATION:{parts_wx[1]}")
            if len(parts_wx) >= 3 and parts_wx[2]:
                out.add(f"WSTAT:{parts_wx[1]}:{parts_wx[2]}")
    return out


def resolve_canonical_fee_source(fee_rate: float, sleeve_src: str = "", explicit_source: str = "") -> str:
    """Maps authoritative fee rate + sleeve into canonical `fee_source` (`zero_fees`, `weather_fees_v2`, `sports_fees_v2`, `crypto_fees_v2`)."""
    fr = max(0.0, float(fee_rate or 0.0))
    if fr <= 1e-9:
        return "zero_fees"
    exp_s = str(explicit_source or "").strip()
    if exp_s and exp_s not in {"crypto_fees_v2", "zero_fees"}:
        return exp_s
    sl_u = str(sleeve_src or "").strip().upper()
    if sl_u.startswith(("W_PRUNE", "W1_")) or "WEATHER" in sl_u or "METAR" in sl_u:
        return "weather_fees_v2"
    if any(t in sl_u for t in ("SPORT", "NBA", "NFL", "SOCCER", "TENNIS", "ESPORT")) or sl_u.startswith(("SP", "SOC", "TEN", "API", "CL1_", "DC1_", "LP_COMP1_", "MOO_")):
        return "sports_fees_v2"
    return exp_s or "crypto_fees_v2"


def compute_reconciled_concentration_nav_usd(harvester: Any, now_ts: Optional[float] = None) -> float:
    """
    Section 7(a)/(b) Authoritative Reconciled Mark-to-Bid NAV:
      - Sums unencumbered exchange cash (`_last_known_collateral`), escrowed maker equity already
        deducted on-chain (`pending_intents_synced_equity_usd`), and conservative open position value.
      - Fails closed to `$0.00` when `_last_known_collateral is None` in live mode (`not dry_run`).
      - NEVER inflates NAV with raw book cost of UMA-disputed (`umaResolutionStatus == 'disputed'`),
        post-expiry UMA-frozen (`is_post_expiry_uma_frozen_lock`), legged-out residual (`MULTI_LEG_RESIDUAL` /
        `is_legged_out_residual` / `_UNWRESID_`), or unresolved balance discrepancy positions (such as the
        4 disputed KMIA positions locking `$50.51` book cost), valuing impaired positions strictly at
        `min(notional_usd, remaining_shares * verified_best_bid)` (`$0.00` when no live bid exists).
      - Applies ZERO artificial `$25.00` floor so concentration caps scale down proportionally with true NAV.
    """
    if harvester is None:
        return 0.0
    now_f = float(time.time() if now_ts is None else now_ts)
    collat_raw = getattr(harvester, "_last_known_collateral", None)
    if collat_raw is None:
        collat_f = 75.0 if bool(getattr(harvester, "dry_run", False)) else 0.0
    else:
        try:
            collat_f = float(collat_raw)
        except (TypeError, ValueError):
            collat_f = 0.0
    if not math.isfinite(collat_f) or collat_f < 0.0:
        collat_f = 0.0

    act_pos = getattr(harvester, "active_positions", None) or {}
    open_val = 0.0
    for p in act_pos.values():
        if not isinstance(p, Mapping):
            continue
        st_u = str(p.get("status") or "").strip().upper()
        if st_u == "AWAITING_ONCHAIN_SETTLEMENT" or p.get("resolved_winning_outcome") is not None:
            continue
        raw_not = _sf(p.get("notional_usd"), 0.0)
        if raw_not <= 0.0:
            continue
        rem_sh = _sf(p.get("remaining_shares", p.get("entry_shares")), 0.0)
        bid_px = _sf(p.get("best_bid", p.get("current_bid", p.get("mark_bid"))), 0.0)
        is_impaired = bool(
            str(p.get("umaResolutionStatus") or "").strip().lower() == "disputed"
            or is_post_expiry_uma_frozen_lock(p, now_f)
            or bool(p.get("is_legged_out_residual"))
            or str(p.get("box_type") or "").strip().upper() == "MULTI_LEG_RESIDUAL"
            or "_UNWRESID_" in str(p.get("trade_id") or "").upper()
            or st_u in {"UNRESOLVED_BALANCE_DISCREPANCY", "UNRESOLVED_SETTLEMENT", "EXPIRED_OUT_OF_MONEY"}
        )
        if is_impaired:
            if rem_sh > 0.0 and 0.0 < bid_px <= 1.0:
                open_val += min(raw_not, rem_sh * bid_px)
        else:
            if rem_sh > 0.0 and 0.0 < bid_px <= 1.0:
                open_val += min(raw_not, rem_sh * bid_px)
            else:
                open_val += raw_not
    escrowed_maker_eq = pending_intents_synced_equity_usd(getattr(harvester, "pending_entry_intents", None))
    return round(max(0.0, collat_f + open_val + escrowed_maker_eq), 4)


def is_disputed_or_frozen_uma_position(p: Mapping[str, Any], now_ts: Optional[float] = None) -> bool:
    """True when a position is UMA-disputed, post-expiry UMA-frozen, or one of the 4 protected KMIA locks (`D-001`/`D-007`)."""
    if not isinstance(p, Mapping):
        return False
    st_u = str(p.get("status") or "").strip().upper()
    return bool(
        str(p.get("market_id") or "").strip() in {"6707502", "6707503"}
        or str(p.get("umaResolutionStatus") or "").strip().lower() == "disputed"
        or is_post_expiry_uma_frozen_lock(p, now_ts)
        or bool(p.get("is_legged_out_residual"))
        or str(p.get("box_type") or "").strip().upper() == "MULTI_LEG_RESIDUAL"
        or "_UNWRESID_" in str(p.get("trade_id") or "").upper()
        or st_u in {"UNRESOLVED_BALANCE_DISCREPANCY", "UNRESOLVED_SETTLEMENT", "EXPIRED_OUT_OF_MONEY"}
    )


def resolve_missing_opp_token_id(
    harvester: Any,
    market_id: str,
    condition_id: str,
    leg_token_id: str,
    *,
    timeout_sec: float = 1.5,
) -> str:
    """Bounded LRU resolver for binary complement token IDs when cross-market 2-leg/1-leg candidates omit `opp_token_id`."""
    tok_s = str(leg_token_id or "").strip()
    mid_s = str(market_id or "").strip()
    cid_s = str(condition_id or "").strip()
    if not tok_s:
        return ""
    cache: Dict[str, Any] = (
        harvester.__dict__.setdefault("_opp_token_id_cache", {})
        if harvester is not None and hasattr(harvester, "__dict__")
        else {}
    )
    now_f = time.time()
    hit = cache.get(tok_s)
    if isinstance(hit, str) and hit and hit != tok_s:
        return hit
    if isinstance(hit, tuple) and len(hit) == 2 and (now_f - float(hit[1] or 0.0)) < 30.0:
        return str(hit[0] or "")

    w_map = getattr(harvester, "_clinched_ws_watchlist", None) if harvester is not None else None
    if isinstance(w_map, Mapping):
        w_ent = w_map.get(tok_s)
        if isinstance(w_ent, Mapping):
            w_opp = str(w_ent.get("opp_token_id") or w_ent.get("leg_a_opp_token_id") or "").strip()
            if len(w_opp) >= 10 and w_opp != tok_s:
                cache[tok_s] = w_opp
                return w_opp

    urls: List[str] = []
    if mid_s.isdigit():
        urls.append(f"https://gamma-api.polymarket.com/markets/{mid_s}")
    if cid_s.startswith("0x") and len(cid_s) >= 10:
        urls.append(f"https://clob.polymarket.com/markets/{cid_s}")

    for url in urls:
        try:
            req = urllib.request.Request(url, headers={"User-Agent": "Dominus-Harvester/5.0", "Accept": "application/json"})
            with urllib.request.urlopen(req, timeout=max(0.3, float(timeout_sec))) as resp:
                payload = json.loads(resp.read().decode("utf-8", errors="replace"))
            if not isinstance(payload, Mapping):
                continue
            cand_toks: List[str] = []
            raw_ct = payload.get("clobTokenIds")
            if isinstance(raw_ct, str) and raw_ct.strip():
                try:
                    parsed_ct = json.loads(raw_ct)
                    if isinstance(parsed_ct, list):
                        cand_toks.extend(str(x).strip() for x in parsed_ct if str(x).strip())
                except Exception:
                    pass
            elif isinstance(raw_ct, list):
                cand_toks.extend(str(x).strip() for x in raw_ct if str(x).strip())
            raw_tlist = payload.get("tokens")
            if isinstance(raw_tlist, list):
                for tobj in raw_tlist:
                    if isinstance(tobj, Mapping):
                        tid = str(tobj.get("token_id") or tobj.get("tokenId") or "").strip()
                        if tid:
                            cand_toks.append(tid)
            uniq = list(dict.fromkeys(t for t in cand_toks if len(t) >= 10))
            if len(uniq) == 2 and tok_s in uniq:
                opp = uniq[1] if uniq[0] == tok_s else uniq[0]
                if len(cache) >= 2048:
                    cache.clear()
                cache[uniq[0]] = uniq[1]
                cache[uniq[1]] = uniq[0]
                return opp
        except Exception:
            continue
    if len(cache) < 2048:
        cache[tok_s] = ("", now_f)
    return ""


def resolve_unencumbered_partner_inventory_and_leg_cap(
    harvester: Any,
    cand: Mapping[str, Any],
    partner_tok: str,
    default_max_box_net: float = 0.994,
    now_ts: Optional[float] = None,
    *,
    exclude_intent_id: str = "",
    verify_wallet: Optional[bool] = None,
) -> Tuple[float, float, float]:
    """
    Returns `(unencumbered_partner_shares, partner_cost_per_share, clamped_leg_a_cap)` for
    inventory-backed 1-leg completions (`C1` / `D1` / `CAL1`), preventing `> $1.00` pair cost
    and partner-share double-pledging (`BUG-W3-MP-1`).
    """
    ptok = str(partner_tok or "").strip()
    if not ptok:
        return 0.0, 0.0, 0.0
    gross_unpaired_sh = 0.0
    encumbered_onchain_sh = 0.0
    pledged_sh = 0.0
    cost_num = 0.0
    cost_den = 0.0
    act_map = getattr(harvester, "active_positions", None) if harvester is not None else None
    if isinstance(act_map, Mapping):
        for _p in act_map.values():
            if not isinstance(_p, Mapping):
                continue
            _sh = max(0.0, float(_p.get("remaining_shares", _p.get("entry_shares", _p.get("shares"))) or 0.0))
            if _sh <= 0.0:
                continue
            if not position_is_settlement_receivable(_p) and str(_p.get("partner_held_token_id") or "").strip() == ptok:
                pledged_sh += _sh
            if str(_p.get("token_id") or "").strip() != ptok or position_is_settlement_receivable(_p):
                continue
            if (
                is_disputed_or_frozen_uma_position(_p, now_ts)
                or bool(_p.get("is_dominance_box"))
                or bool(str(_p.get("box_partner_trade_id") or "").strip())
                or bool(_p.get("inventory_backed_completion"))
            ):
                encumbered_onchain_sh += _sh
                continue
            gross_unpaired_sh += _sh
            _rcb = _p.get("remaining_cost_basis")
            if _rcb is None:
                _rcb = _p.get("notional_usd")
            if _rcb is None and _p.get("entry_price") is not None:
                _rcb = float(_p.get("entry_price") or 0.0) * _sh
            _fee = _p.get("entry_fee_cash_usd", _p.get("entry_fee_cash", _p.get("fee_usd", 0.0)))
            _pos_cost = max(0.0, float(_rcb or 0.0)) + max(0.0, float(_fee or 0.0))
            if _pos_cost > 0.0:
                cost_num += _pos_cost
                cost_den += _sh
    pend_map = getattr(harvester, "pending_entry_intents", None) if harvester is not None else None
    if isinstance(pend_map, Mapping):
        for _iid, _it in pend_map.items():
            if exclude_intent_id and str(_iid) == exclude_intent_id:
                continue
            if isinstance(_it, Mapping) and str(_it.get("partner_held_token_id") or "").strip() == ptok:
                pledged_sh += max(0.0, float(_it.get("posted_shares", _it.get("shares")) or 0.0))
    prepost_p = getattr(harvester, "_prepost_partner_pledged_shares", None) if harvester is not None else None
    if isinstance(prepost_p, Mapping):
        for _iid_p, _pv in prepost_p.items():
            if exclude_intent_id and str(_iid_p) == exclude_intent_id:
                continue
            if isinstance(_pv, tuple) and len(_pv) == 2 and str(_pv[0] or "").strip() == ptok:
                pledged_sh += max(0.0, float(_pv[1] or 0.0))
    avail_sh = max(0.0, gross_unpaired_sh - pledged_sh)
    _do_wallet = bool(harvester is not None and not bool(getattr(harvester, "dry_run", True))) if verify_wallet is None else bool(verify_wallet)
    ex = getattr(harvester, "executor", None) if harvester is not None else None
    has_bal_fn = any(callable(getattr(ex, m, None)) for m in ("get_onchain_erc1155_balance", "get_conditional_balance", "get_token_balance")) if ex is not None else False
    if has_bal_fn and (_do_wallet or gross_unpaired_sh <= 0.0):
        from src.polymarket_research.stage_c_zero_loss_velocity import _query_executor_verified_token_balance
        _w_free = max(0.0, float(_query_executor_verified_token_balance(harvester, ptok) or 0.0) - encumbered_onchain_sh - pledged_sh)
        avail_sh = _w_free if gross_unpaired_sh <= 0.0 else (min(avail_sh, _w_free) if _do_wallet else max(avail_sh, _w_free))
    _cand_cost_ps = max(0.0, float(cand.get("partner_avg_cost_ps") or 0.0)) if isinstance(cand, Mapping) else 0.0
    _pos_cost_ps = (cost_num / cost_den) if cost_den > 1e-9 else 0.0
    partner_cost_ps = round(max(_pos_cost_ps, _cand_cost_ps), 6)
    raw_box_cap = min(0.9985, float((cand.get("max_box_cost_net") if isinstance(cand, Mapping) else None) or default_max_box_net))
    pair_rem_cap = round(raw_box_cap - partner_cost_ps, 4)
    _raw_la_cap = (
        cand.get("leg_a_max_price") or cand.get("leg_a_limit_price") or cand.get("anchor_bid_px")
        if isinstance(cand, Mapping)
        else None
    )
    cand_leg_a_cap = float(_raw_la_cap) if (_raw_la_cap is not None and float(_raw_la_cap or 0.0) > 0.0) else raw_box_cap
    clamped_leg_a_cap = round(min(cand_leg_a_cap, pair_rem_cap), 4)
    return avail_sh, partner_cost_ps, clamped_leg_a_cap


def check_harvester_fail_closed_accounting_halt(
    harvester: Any,
    default_state_file: Optional[Path] = None,
) -> List[str]:
    """
    Section 7(c) Fail-Closed Accounting Invariants:
      1. Halts immediately if `ACCOUNTING_SAFEGUARD_ACTIVE.json` (`active: true`) was triggered by `PAAAccountant`.
      2. Halts immediately on non-finite or negative `_last_known_collateral`.
      3. Halts immediately on corrupt/negative `remaining_shares` or `notional_usd` in `active_positions`.
    """
    reasons: List[str] = []
    if harvester is None:
        return reasons
    collat_raw = getattr(harvester, "_last_known_collateral", None)
    if collat_raw is not None:
        try:
            cf = float(collat_raw)
            if not math.isfinite(cf) or cf < -1e-6:
                reasons.append("ACCOUNTING_INVALID_NEGATIVE_OR_NAN_COLLATERAL")
        except (TypeError, ValueError):
            reasons.append("ACCOUNTING_CORRUPT_COLLATERAL_STATE")

    act_pos = getattr(harvester, "active_positions", None) or {}
    for tid, p in act_pos.items():
        if not isinstance(p, Mapping):
            reasons.append(f"ACCOUNTING_CORRUPT_POSITION_RECORD:{tid}")
            continue
        for fld in ("notional_usd", "remaining_shares"):
            if fld in p and p.get(fld) is not None:
                try:
                    fv = float(p[fld])
                    if not math.isfinite(fv) or fv < -1e-6:
                        reasons.append(f"ACCOUNTING_NEGATIVE_POSITION_FIELD:{tid}:{fld}")
                except (TypeError, ValueError):
                    reasons.append(f"ACCOUNTING_NONNUMERIC_POSITION_FIELD:{tid}:{fld}")

    sg_path = getattr(harvester, "accounting_safeguard_file", None)
    if sg_path is None and default_state_file is not None:
        try:
            sg_path = Path(default_state_file).parent / "paa" / "ACCOUNTING_SAFEGUARD_ACTIVE.json"
        except Exception:
            sg_path = None
    if sg_path is not None:
        try:
            sg_p = Path(sg_path)
            if sg_p.exists():
                sg_obj = json.loads(sg_p.read_text(encoding="utf-8"))
                if not isinstance(sg_obj, Mapping) or sg_obj.get("active", True) is not False:
                    reasons.append("PAA_ACCOUNTING_SAFEGUARD_HALT")
        except Exception:
            reasons.append("PAA_ACCOUNTING_SAFEGUARD_UNREADABLE_FAIL_CLOSED")
    return reasons


def check_per_event_concentration_cap(
    harvester: Any,
    cand: Optional[Mapping[str, Any]],
    market_ids: Optional[Sequence[str]] = None,
    now_ts: Optional[float] = None,
    *,
    enforce_override: bool = False,
    min_headroom_usd: float = 5.0,
    exclude_intent_ids: Optional[Sequence[str]] = None,
) -> Tuple[bool, str, float, str]:
    """
    Unified cross-sleeve per-event slot & USD concentration guard across `WS_SNIPE`, `S2`, Taker/Maker
    `SINGLE_LEG_LOCK`, `MULTI_LEG_BUNDLE`, `NEGRISK_CONVERT`, `NEGRISK_2LEG`, and `COMPLETE_SET`.
    Enforces a hard `<= 15%` reconciled mark-to-bid NAV ceiling per correlated weather station/day OR
    non-box oracle event aggregated across ALL strategies and sleeves without sleeve-name or standalone-MKT bypasses.
    Returns `(allowed, reject_reason, remaining_event_headroom_usd, primary_event_group_key)`.
    """
    evt_k = extract_sll_event_group_key(cand)
    cand_keys = extract_canonical_event_keys(cand, market_ids=market_ids)
    if not evt_k and cand_keys:
        evt_k = sorted(cand_keys)[0]
    if harvester is None or not isinstance(cand, Mapping) or not cand_keys:
        return True, "", 9999.0, evt_k
    sl_src = str(cand.get("sleeve_source") or cand.get("sleeve") or "").strip()
    btype = str(cand.get("box_type") or "").strip().upper()
    rem_s = float(cand.get("rem_sec") or 9999.0)
    has_wx_key = any(str(k).startswith(("WSTAT:", "EVTWX:", "WXSTATION:")) for k in cand_keys)
    # Only pure 2-leg opposing-outcome non-weather short-TTE D1 boxes skip single-oracle concentration caps;
    # single-leg S2 and any weather-station candidate MUST ALWAYS pass the 15% reconciled NAV cap!
    if btype == "DOMINANCE" and rem_s <= 960.0 and sl_src == "D1_SAME_ORACLE_DOMINANCE_BOX" and not has_wx_key:
        return True, "", 9999.0, evt_k
    ex = getattr(harvester, "executor", None)
    enforce = bool(
        enforce_override
        or getattr(harvester, "enforce_event_concentration_cap", False)
        or getattr(harvester, "enforce_bond1_smart_queue", False)
        or (
            not getattr(harvester, "dry_run", True)
            and getattr(ex, "client", None) is not None
            and getattr(getattr(ex, "client", None), "_mock_children", None) is None
            and "execute_snipe_order" not in getattr(ex, "__dict__", {})
            and "place_fok_order" not in getattr(ex, "__dict__", {})
            and "execute_fok_order" not in getattr(ex, "__dict__", {})
            and "post_maker_entry_order" not in getattr(ex, "__dict__", {})
        )
    )
    if not enforce:
        return True, "", 9999.0, evt_k
    from src.polymarket_research.holistic_strategy_governance import GLOBAL_GOVERNANCE_MANAGER

    rb_cfg = GLOBAL_GOVERNANCE_MANAGER.snapshot.get("riskless_boxes", {})
    if not bool(rb_cfg.get("enable_event_slot_diversification", True)):
        return True, "", 9999.0, evt_k
    now_f = float(time.time() if now_ts is None else now_ts)
    stalk_map = getattr(harvester, "_sll_event_stalk_until", None) or {}
    for ck in cand_keys:
        if float(stalk_map.get(ck, 0.0) or 0.0) > now_f:
            return False, "EVENT_STALKER_COOLDOWN", 0.0, evt_k

    act_pos = getattr(harvester, "active_positions", None) or {}
    pend_int = getattr(harvester, "pending_entry_intents", None) or {}
    prepost_evts = getattr(harvester, "_prepost_sll_events", None) or {}
    excl_ids = {str(x).strip() for x in (exclude_intent_ids or ()) if str(x or "").strip()}
    reconciled_nav = compute_reconciled_concentration_nav_usd(harvester, now_f)
    caps = compute_dynamic_riskless_tier_caps(reconciled_nav, rb_cfg)
    max_slots = int(caps.get("max_concurrent_intents_per_event", 1) or 1)
    max_evt_usd = float(caps.get("max_event_notional_usd", 25.0) or 25.0)
    is_weather_or_non_box_oracle = bool(
        has_wx_key or btype not in {"DOMINANCE", "DOMINANCE_BOX", "COMPLETE_SET", "C1_BINARY_COMPLETE_SET"}
    )
    if is_weather_or_non_box_oracle:
        corr_pct = min(0.15, max(0.01, float(rb_cfg.get("max_correlated_oracle_event_nav_pct", 0.15) or 0.15)))
        corr_cap_usd = round(reconciled_nav * corr_pct, 4)
        if float(rb_cfg.get("max_event_notional_usd", 0.0) or 0.0) > 0.0:
            max_evt_usd = min(max_evt_usd, corr_cap_usd)
        else:
            max_evt_usd = corr_cap_usd

    mset = {str(m).strip() for m in (market_ids or ()) if str(m or "").strip()}
    if not mset:
        m0 = str(cand.get("leg_a_market_id") or cand.get("market_id") or "").strip()
        if m0:
            mset.add(m0)

    _partner_complete_tok = (
        str(cand.get("partner_held_token_id") or (cand.get("leg_a_opp_token_id") if sl_src == "C1_BINARY_COMPLETE_SET" else "") or "").strip()
        if btype in {"SINGLE_LEG_LOCK", "SINGLE_LEG_MAKER_LOCK"}
        and sl_src in {"C1_BINARY_COMPLETE_SET", "D1_SAME_ORACLE_DOMINANCE_BOX", "CAL1_DEADLINE_SURVIVAL_AND_SCALAR_LADDER_BOX"}
        and (bool(cand.get("full_throttle_bridge")) or cand.get("rule_verified") is True or bool(cand.get("_inventory_backed_maker")))
        else ""
    )
    seen_slot_groups: set[str] = set()
    other_mkt_slot_groups: set[str] = set()
    used_evt_usd = 0.0
    for pid, p in act_pos.items():
        if not isinstance(p, Mapping):
            continue
        if str(p.get("status") or "") == "AWAITING_ONCHAIN_SETTLEMENT" or p.get("resolved_winning_outcome") is not None:
            continue
        p_keys = extract_canonical_event_keys(p)
        if not (cand_keys & p_keys):
            continue
        used_evt_usd += max(0.0, float(p.get("notional_usd", 0.0) or 0.0))
        if (
            _partner_complete_tok
            and str(p.get("token_id") or "").strip() == _partner_complete_tok
            and not bool(p.get("is_dominance_box"))
            and not bool(p.get("inventory_backed_completion"))
            and not is_disputed_or_frozen_uma_position(p, now_f)
        ):
            continue
        grp_id = str(p.get("box_id") or p.get("trade_id") or pid)
        seen_slot_groups.add(grp_id)
        p_mid = str(p.get("market_id") or "").strip()
        if not mset or p_mid not in mset:
            other_mkt_slot_groups.add(grp_id)

    for ik, iv in pend_int.items():
        if str(ik).strip() in excl_ids or not isinstance(iv, Mapping):
            continue
        iv_notional = max(0.0, float(iv.get("notional_usd", 0.0) or 0.0))
        if iv_notional <= 0.0 and not iv.get("live_maker_anchor_inflight"):
            continue
        i_keys = extract_canonical_event_keys(iv)
        if not (cand_keys & i_keys):
            continue
        used_evt_usd += iv_notional
        grp_id = f"INTENT:{iv.get('inflight_key') or ik}"
        seen_slot_groups.add(grp_id)
        i_mid = str(iv.get("market_id") or "").strip()
        if not mset or i_mid not in mset:
            other_mkt_slot_groups.add(grp_id)

    for pk, pv in prepost_evts.items():
        pk_s = str(pk).strip()
        if pk_s in excl_ids or pk_s in pend_int or not isinstance(pv, Mapping):
            continue
        pv_keys = extract_canonical_event_keys(pv)
        if not (cand_keys & pv_keys):
            continue
        used_evt_usd += max(0.0, float(pv.get("notional_usd", 0.0) or 0.0))
        grp_id = f"PREPOST:{pv.get('inflight_key') or pk_s}"
        seen_slot_groups.add(grp_id)
        pv_mid = str(pv.get("market_id") or "").strip()
        if not mset or pv_mid not in mset:
            other_mkt_slot_groups.add(grp_id)

    rem_evt_usd = round(max(0.0, max_evt_usd - used_evt_usd), 4)
    if len(other_mkt_slot_groups) >= max_slots:
        return False, "MAX_CONCURRENT_PER_EVENT_REACHED", rem_evt_usd, evt_k
    if len(seen_slot_groups) >= max_slots and btype in {
        "SINGLE_LEG_LOCK",
        "SINGLE_LEG_MAKER_LOCK",
        "MULTI_LEG_BUNDLE",
        "NEGRISK_CONVERT",
        "NEGRISK_2LEG",
        "COMPLETE_SET",
    }:
        return False, "MAX_CONCURRENT_PER_EVENT_REACHED", rem_evt_usd, evt_k
    eff_min_hr = (
        min(float(min_headroom_usd), max(1.0, 5.0 * float(cand.get("anchor_bid_px") or cand.get("leg_a_limit_price") or 0.90)))
        if _partner_complete_tok
        else float(min_headroom_usd)
    )
    if rem_evt_usd < eff_min_hr:
        return False, "MAX_EVENT_NOTIONAL_CAP_REACHED", rem_evt_usd, evt_k
    if getattr(harvester, "enforce_v6_cwce_and_reservation", False):
        v6_chk = evaluate_candidate_v6_cwce_and_reservation(
            harvester,
            cand,
            market_ids=market_ids,
            now_ts=now_f,
            exclude_intent_ids=exclude_intent_ids,
        )
        harvester._last_cwce_verdict = v6_chk.get("cwce_verdict")
        if not v6_chk["allowed"]:
            return (
                False,
                str(v6_chk["reason"]),
                float(v6_chk.get("remaining_cluster_headroom_usd", rem_evt_usd)),
                evt_k,
            )
    return True, "", rem_evt_usd, evt_k


