def _enable_ws_nodelay(ws: Any) -> bool:
    try:
        tr = getattr(ws, "transport", None)
        sock = tr.get_extra_info("socket") if tr is not None else None
        if sock is not None:
            sock.setsockopt(socket.IPPROTO_TCP, socket.TCP_NODELAY, 1)
            return True
    except Exception:
        pass
    return False

