#!/usr/bin/env python3
"""
polymarket_direct_feeds.py
==========================
`$0.00/mo` Official League `liveData` Push Adapters & Dual-Source Conservative Reconcilers
for pure-riskless mathematical sports clinch sleeves (`SP2_NBA_ENDGAME_LOCK`, `CL1_MULTISPORT_POST_REVIEW_SCORE_CLINCH`,
`AFF1_FROZEN_SUBPERIOD_COLLAPSE`).

Endpoints (unauthenticated official league JSON feeds over persistent keep-alive TLS):
  1. NBA Official CDN (`https://cdn.nba.com/static/json/liveData/scoreboard/todaysScoreboard_00.json`)
  2. NHL Official Web API (`https://api-web.nhle.com/v1/score/now`)
  3. MLB Official StatsAPI (`https://statsapi.mlb.com/api/v1/schedule?sportId=1&hydrate=linescore`)

Zero-Loss Reconciliation Invariants:
  - Monotonic scores (`OVER` / period clinch): when both ESPN and the official league feed match a game,
    we take `min(espn_score, official_score)` and `max(espn_clock_sec, official_clock_sec)` so a single-feed
    typo or premature score increment can NEVER trigger a phantom pre-review lock!
  - `completed=True` (`FINAL` post-game clinch): allowed ONLY when the game is `post` AND if both feeds
    see the game, both agree `completed == True` with identical `(home_score, away_score)`!
  - If ESPN lags behind on discovering an active game or temporarily 503s, official league `FINAL` games
    (`completed == True` with `period >= regulation_periods` and `home_score != away_score`) provide zero-cost
    sub-second backup coverage, while in-play monotonic locks still pass through `ScoreConfirmationTracker`'s
    mandatory `90s` (`NHL`) / `75s` (`NFL`) / `180s` (`SOCCER`) anti-VAR hold timer.
"""

# from __future__ import annotations  # (Lifted to top of consolidated bundle)

import logging
import threading
from typing import Any, Dict, List, Optional, Tuple

import requests

from src.polymarket_research.riskless_frontier_v3_engine import LiveMultiSportGame
from src.polymarket_research.tradfi_sports_zero_fee_engine import _norm_team, _parse_iso_ts
from src.polymarket_research.uma_nba_endgame_engine import (
    CDN_NBA_SCOREBOARD_URL,
    LiveNbaGameState,
    _canon_nba_team,
    _parse_iso_clock_sec,
)

logger = logging.getLogger("PolymarketDirectFeeds")

NHL_OFFICIAL_SCORE_URL = "https://api-web.nhle.com/v1/score/now"
MLB_OFFICIAL_SCHEDULE_URL = "https://statsapi.mlb.com/api/v1/schedule?sportId=1&hydrate=linescore"
ESPN_TENNIS_SCOREBOARD_TMPL = "https://site.api.espn.com/apis/site/v2/sports/tennis/{tour}/scoreboard"

_SESSION_LOCAL = threading.local()
_CONDITIONAL_CACHE_LOCK = threading.Lock()
_CONDITIONAL_URL_CACHE: Dict[str, Dict[str, Any]] = {}


def _get_conditional_json_sync(url: str, *, timeout: float = 2.5) -> Optional[Dict[str, Any]]:
    """Persistent keep-alive GET with `If-None-Match`/`If-Modified-Since` so 0.5s endgame polls cost near-zero on 304."""
    sess = _get_keepalive_session()
    with _CONDITIONAL_CACHE_LOCK:
        ent = _CONDITIONAL_URL_CACHE.get(url)
        hdrs: Dict[str, str] = {}
        if ent:
            if ent.get("etag"):
                hdrs["If-None-Match"] = ent["etag"]
            if ent.get("last_modified"):
                hdrs["If-Modified-Since"] = ent["last_modified"]
    resp = sess.get(url, headers=hdrs, timeout=timeout)
    if resp.status_code == 304 and ent is not None:
        return ent.get("payload")
    if resp.status_code == 200:
        data = resp.json()
        with _CONDITIONAL_CACHE_LOCK:
            _CONDITIONAL_URL_CACHE[url] = {
                "etag": resp.headers.get("ETag", ""),
                "last_modified": resp.headers.get("Last-Modified", ""),
                "payload": data,
            }
            if len(_CONDITIONAL_URL_CACHE) > 64:
                _CONDITIONAL_URL_CACHE.pop(next(iter(_CONDITIONAL_URL_CACHE)), None)
        return data
    return None


def compute_adaptive_sports_poll_interval_sec(
    *,
    is_endgame_or_halftime: bool = False,
    has_live_games: bool = True,
) -> float:
    """Adaptive cadence (`0.5s` inside final 120s / halftime freeze, `5.5s` normal live, `60s` idle)."""
    if is_endgame_or_halftime:
        return 0.75
    return 5.5 if has_live_games else 60.0


def _get_keepalive_session() -> requests.Session:
    sess = getattr(_SESSION_LOCAL, "session", None)
    if sess is None:
        sess = requests.Session()
        sess.headers.update(
            {
                "User-Agent": "Mozilla/5.0 (compatible; DominusDirectFeed/1.0)",
                "Accept": "application/json",
                "Connection": "keep-alive",
            }
        )
        _SESSION_LOCAL.session = sess
    return sess


def parse_nba_cdn_scoreboard(payload: Dict[str, Any]) -> List[LiveNbaGameState]:
    """Parses official `cdn.nba.com` `todaysScoreboard_00.json` into `LiveNbaGameState` objects."""
    sb = (payload or {}).get("scoreboard") if isinstance((payload or {}).get("scoreboard"), dict) else (payload or {})
    games_raw = sb.get("games") if isinstance(sb, dict) else []
    out: List[LiveNbaGameState] = []
    for g in games_raw or []:
        if not isinstance(g, dict):
            continue
        gid = str(g.get("gameId") or "").strip()
        st_code = int(g.get("gameStatus") or 0)  # 1=pre, 2=in, 3=post (Final)
        state = "post" if st_code == 3 else ("in" if st_code == 2 else "pre")
        completed = st_code == 3
        period = int(g.get("period") or 0)
        clk_sec = 0.0 if completed else _parse_iso_clock_sec(g.get("gameClock"))
        start_ts = _parse_iso_ts(g.get("gameTimeUTC") or g.get("gameEt")) or 0.0
        ht = g.get("homeTeam") if isinstance(g.get("homeTeam"), dict) else {}
        at = g.get("awayTeam") if isinstance(g.get("awayTeam"), dict) else {}
        h_city = str(ht.get("teamCity") or "").strip()
        h_nick = str(ht.get("teamName") or "").strip()
        h_name = (f"{h_city} {h_nick}".strip() if (h_city and h_nick and h_city.lower() not in h_nick.lower()) else (h_nick or h_city))
        a_city = str(at.get("teamCity") or "").strip()
        a_nick = str(at.get("teamName") or "").strip()
        a_name = (f"{a_city} {a_nick}".strip() if (a_city and a_nick and a_city.lower() not in a_nick.lower()) else (a_nick or a_city))
        h_abbr = str(ht.get("teamTricode") or "").strip().upper()
        a_abbr = str(at.get("teamTricode") or "").strip().upper()
        try:
            h_sc = int(float(ht.get("score") or 0))
            a_sc = int(float(at.get("score") or 0))
        except Exception:
            continue
        if gid and h_name and a_name:
            out.append(
                LiveNbaGameState(
                    game_id=gid,
                    start_ts=start_ts,
                    state=state,
                    completed=completed,
                    period=period,
                    clock_sec=clk_sec,
                    home_name=h_name,
                    home_abbr=h_abbr,
                    home_score=h_sc,
                    away_name=a_name,
                    away_abbr=a_abbr,
                    away_score=a_sc,
                    source="nba_cdn",
                )
            )
    return out


def fetch_nba_cdn_scoreboard_sync(timeout: float = 2.8) -> List[LiveNbaGameState]:
    try:
        payload = _get_conditional_json_sync(CDN_NBA_SCOREBOARD_URL, timeout=timeout)
        if isinstance(payload, dict):
            return parse_nba_cdn_scoreboard(payload)
    except Exception as exc:
        logger.debug(f"NBA CDN direct feed fetch notice: {exc}")
    return []


def _extract_nhl_team_str(team_obj: Dict[str, Any]) -> str:
    for k in ("commonName", "name", "placeName"):
        v = team_obj.get(k)
        if isinstance(v, dict):
            s = str(v.get("default") or "").strip()
            if s:
                return s
        elif isinstance(v, str) and v.strip():
            return v.strip()
    return str(team_obj.get("abbrev") or "").strip()


def parse_nhl_official_scoreboard(payload: Dict[str, Any]) -> List[LiveMultiSportGame]:
    """Parses `https://api-web.nhle.com/v1/score/now` into `LiveMultiSportGame` records."""
    games_raw = (payload or {}).get("games") if isinstance(payload, dict) else []
    out: List[LiveMultiSportGame] = []
    for g in games_raw or []:
        if not isinstance(g, dict):
            continue
        gs = str(g.get("gameState") or "").strip().upper()
        if gs == "OFF":
            state, completed = "post", True
        elif gs in ("FINAL", "LIVE", "CRIT"):
            state, completed = "in", False
        else:
            continue
        gid = str(g.get("id") or "").strip()
        start_ts = _parse_iso_ts(g.get("startTimeUTC")) or 0.0
        pd_desc = g.get("periodDescriptor") if isinstance(g.get("periodDescriptor"), dict) else {}
        period = int(pd_desc.get("number") or g.get("period") or 0)
        clk_obj = g.get("clock") if isinstance(g.get("clock"), dict) else {}
        in_intermission = bool(clk_obj.get("inIntermission", False))
        clk_sec = (
            0.0
            if completed
            else float(
                clk_obj.get("secondsRemaining")
                if clk_obj.get("secondsRemaining") is not None
                else _parse_iso_clock_sec(clk_obj.get("timeRemaining"))
            )
        )
        ht = g.get("homeTeam") if isinstance(g.get("homeTeam"), dict) else {}
        at = g.get("awayTeam") if isinstance(g.get("awayTeam"), dict) else {}
        h_name = _extract_nhl_team_str(ht)
        a_name = _extract_nhl_team_str(at)
        try:
            h_sc = int(float(ht.get("score") or 0))
            a_sc = int(float(at.get("score") or 0))
        except Exception:
            continue
        ls_h: Dict[int, int] = {}
        ls_a: Dict[int, int] = {}
        # Derive per-period goal totals when goals[] list is included in score/now
        if isinstance(g.get("goals"), list):
            h_ab = str(ht.get("abbrev") or "").strip().upper()
            a_ab = str(at.get("abbrev") or "").strip().upper()
            for gl in g.get("goals") or []:
                if not isinstance(gl, dict):
                    continue
                p_num = int((gl.get("periodDescriptor") or {}).get("number") or gl.get("period") or 0)
                t_ab = str((gl.get("teamAbbrev") or {}).get("default") if isinstance(gl.get("teamAbbrev"), dict) else (gl.get("teamAbbrev") or "")).strip().upper()
                if p_num >= 1:
                    if h_ab and t_ab == h_ab:
                        ls_h[p_num] = ls_h.get(p_num, 0) + 1
                    elif a_ab and t_ab == a_ab:
                        ls_a[p_num] = ls_a.get(p_num, 0) + 1
        if gid and h_name and a_name:
            out.append(
                LiveMultiSportGame(
                    sport="NHL",
                    game_id=gid,
                    start_ts=start_ts,
                    state=state,
                    completed=completed,
                    is_halftime=in_intermission and period == 1,
                    period=period,
                    clock_sec=clk_sec,
                    home_name=h_name,
                    away_name=a_name,
                    home_score=h_sc,
                    away_score=a_sc,
                    linescores_home=ls_h,
                    linescores_away=ls_a,
                )
            )
    return out


def fetch_nhl_official_scoreboard_sync(timeout: float = 2.8) -> List[LiveMultiSportGame]:
    try:
        payload = _get_conditional_json_sync(NHL_OFFICIAL_SCORE_URL, timeout=timeout)
        if isinstance(payload, dict):
            return parse_nhl_official_scoreboard(payload)
    except Exception as exc:
        logger.debug(f"NHL official feed fetch notice: {exc}")
    return []


def parse_mlb_statsapi_scoreboard(payload: Dict[str, Any]) -> List[LiveMultiSportGame]:
    """Parses `statsapi.mlb.com/api/v1/schedule?sportId=1&hydrate=linescore` into `LiveMultiSportGame`."""
    out: List[LiveMultiSportGame] = []
    for dt_blk in (payload or {}).get("dates") or []:
        if not isinstance(dt_blk, dict):
            continue
        for g in dt_blk.get("games") or []:
            if not isinstance(g, dict):
                continue
            st = g.get("status") if isinstance(g.get("status"), dict) else {}
            abs_st = str(st.get("abstractGameState") or "").strip().lower()
            det_st = str(st.get("detailedState") or "").strip().lower()
            # Strictly exclude postponed/suspended/cancelled rain-shortened ambiguities unless official Final
            if any(bad in det_st for bad in ("postponed", "suspended", "cancelled", "canceled")):
                continue
            if abs_st == "final" and "final" in det_st:
                state, completed = "post", True
            elif abs_st == "live":
                state, completed = "in", False
            else:
                continue
            gid = str(g.get("gamePk") or "").strip()
            start_ts = _parse_iso_ts(g.get("gameDate")) or 0.0
            ls = g.get("linescore") if isinstance(g.get("linescore"), dict) else {}
            period = int(ls.get("currentInning") or 9 if completed else (ls.get("currentInning") or 0))
            tms = g.get("teams") if isinstance(g.get("teams"), dict) else {}
            hm = tms.get("home") if isinstance(tms.get("home"), dict) else {}
            aw = tms.get("away") if isinstance(tms.get("away"), dict) else {}
            h_name = str((hm.get("team") or {}).get("teamName") or (hm.get("team") or {}).get("name") or "").strip()
            a_name = str((aw.get("team") or {}).get("teamName") or (aw.get("team") or {}).get("name") or "").strip()
            try:
                h_sc = int(float(hm.get("score") if hm.get("score") is not None else ((ls.get("teams") or {}).get("home") or {}).get("runs") or 0))
                a_sc = int(float(aw.get("score") if aw.get("score") is not None else ((ls.get("teams") or {}).get("away") or {}).get("runs") or 0))
            except Exception:
                continue
            ls_h: Dict[int, int] = {}
            ls_a: Dict[int, int] = {}
            for inn in ls.get("innings") or []:
                if isinstance(inn, dict) and inn.get("num"):
                    idx = int(inn["num"])
                    if isinstance(inn.get("home"), dict) and inn["home"].get("runs") is not None:
                        ls_h[idx] = int(inn["home"]["runs"])
                    if isinstance(inn.get("away"), dict) and inn["away"].get("runs") is not None:
                        ls_a[idx] = int(inn["away"]["runs"])
            if gid and h_name and a_name:
                out.append(
                    LiveMultiSportGame(
                        sport="MLB",
                        game_id=gid,
                        start_ts=start_ts,
                        state=state,
                        completed=completed,
                        is_halftime=False,
                        period=period,
                        clock_sec=0.0,
                        home_name=h_name,
                        away_name=a_name,
                        home_score=h_sc,
                        away_score=a_sc,
                        linescores_home=ls_h,
                        linescores_away=ls_a,
                    )
                )
    return out


def fetch_mlb_statsapi_scoreboard_sync(timeout: float = 2.8) -> List[LiveMultiSportGame]:
    try:
        payload = _get_conditional_json_sync(MLB_OFFICIAL_SCHEDULE_URL, timeout=timeout)
        if isinstance(payload, dict):
            return parse_mlb_statsapi_scoreboard(payload)
    except Exception as exc:
        logger.debug(f"MLB StatsAPI direct feed fetch notice: {exc}")
    return []


def reconcile_nba_dual_source_boards(
    espn_board: List[LiveNbaGameState],
    cdn_board: List[LiveNbaGameState],
) -> List[LiveNbaGameState]:
    """
    Conservative dual-source reconciler (`ESPN` + `cdn.nba.com`):
      - When both feeds observe the game:
          * `completed=True` (`state='post'`) ONLY if BOTH report `completed=True` AND identical `(home_score, away_score)`,
            OR if `cdn.nba.com` (official league scorer) reports `completed=True` while ESPN is still in final-seconds `in`
            with `cdn_score >= espn_score` on both sides and non-tied final score!
          * If the two feeds disagree on a `post` final score, downgrades `completed=False` (`state='in'`) to block phantom locks!
          * During `in`-play: uses conservative `min(espn_score, cdn_score)` and `max(espn_clock_sec, cdn_clock_sec)`.
      - When one feed is temporarily empty/unreachable, returns the healthy feed cleanly.
    """
    if not cdn_board:
        return list(espn_board or [])
    if not espn_board:
        return list(cdn_board)

    used_cdn_idx = set()
    merged: List[LiveNbaGameState] = []

    for eg in espn_board:
        eg_hk, eg_ak = _canon_nba_team(eg.home_name), _canon_nba_team(eg.away_name)
        cg: Optional[LiveNbaGameState] = None
        for idx_c, cand_c in enumerate(cdn_board):
            if idx_c in used_cdn_idx:
                continue
            cg_hk, cg_ak = _canon_nba_team(cand_c.home_name), _canon_nba_team(cand_c.away_name)
            if (eg_hk == cg_hk and eg_ak == cg_ak) or (
                _team_tokens_match(eg.home_name, cand_c.home_name)
                and _team_tokens_match(eg.away_name, cand_c.away_name)
            ):
                cg = cand_c
                used_cdn_idx.add(idx_c)
                break
        if cg is None:
            merged.append(eg)
            continue
        scores_match = (eg.home_score == cg.home_score) and (eg.away_score == cg.away_score)
        both_final = bool(eg.completed and cg.completed and scores_match)
        cdn_ahead_final = bool(
            cg.completed
            and not eg.completed
            and cg.period >= 4
            and eg.period >= 4
            and eg.clock_sec <= 35.0
            and cg.home_score != cg.away_score
            and cg.home_score >= eg.home_score
            and cg.away_score >= eg.away_score
        )
        if both_final or cdn_ahead_final:
            merged.append(
                LiveNbaGameState(
                    game_id=eg.game_id,
                    start_ts=eg.start_ts or cg.start_ts,
                    state="post",
                    completed=True,
                    period=max(eg.period, cg.period),
                    clock_sec=0.0,
                    home_name=eg.home_name,
                    home_abbr=eg.home_abbr or cg.home_abbr,
                    home_score=cg.home_score,
                    away_name=eg.away_name,
                    away_abbr=eg.away_abbr or cg.away_abbr,
                    away_score=cg.away_score,
                    source="nba_cdn+espn" if both_final else "nba_cdn_final",
                )
            )
        else:
            # Disagreement or still live -> strictly conservative min-score & max-clock!
            merged.append(
                LiveNbaGameState(
                    game_id=eg.game_id,
                    start_ts=eg.start_ts or cg.start_ts,
                    state="in" if ("in" in (eg.state, cg.state) or "post" in (eg.state, cg.state)) else eg.state,
                    completed=False,
                    period=min(eg.period, cg.period) if (eg.period > 0 and cg.period > 0) else max(eg.period, cg.period),
                    clock_sec=max(eg.clock_sec, cg.clock_sec),
                    home_name=eg.home_name,
                    home_abbr=eg.home_abbr or cg.home_abbr,
                    home_score=min(eg.home_score, cg.home_score),
                    away_name=eg.away_name,
                    away_abbr=eg.away_abbr or cg.away_abbr,
                    away_score=min(eg.away_score, cg.away_score),
                    source="nba_cdn+espn_min",
                )
            )

    for idx_c, cg in enumerate(cdn_board):
        if idx_c not in used_cdn_idx:
            merged.append(cg)
    return merged


def _team_tokens_match(a: str, b: str) -> bool:
    na, nb = _norm_team(a), _norm_team(b)
    if not na or not nb:
        return False
    if na == nb or na in nb or nb in na:
        return True
    ta = [w for w in na.split() if len(w) >= 3]
    tb = [w for w in nb.split() if len(w) >= 3]
    return bool(ta and tb and ta[-1] == tb[-1])


def reconcile_multisport_dual_source_boards(
    sport: str,
    espn_board: List[LiveMultiSportGame],
    official_board: List[LiveMultiSportGame],
) -> List[LiveMultiSportGame]:
    """
    Conservative dual-source reconciler (`ESPN` + Official `NHL` / `MLB` API):
      - Preserves ESPN `game_id` stability so `ScoreConfirmationTracker` anti-VAR timers never reset!
      - Takes conservative `min(espn_score, official_score)` on live games so a single-feed score glitch
        can NEVER trigger an unconfirmed `OVER` lock.
      - Allows `completed=True` (`post`) when both feeds agree on final score OR when the official league
        scorer (`api-web.nhle.com` / `statsapi.mlb.com`) marks `completed=True` with non-decreasing score
        in final regulation/OT!
    """
    if not official_board:
        return list(espn_board or [])
    if not espn_board:
        return list(official_board)

    used_off: set = set()
    merged: List[LiveMultiSportGame] = []
    min_reg_period = 3 if sport.upper() == "NHL" else (9 if sport.upper() == "MLB" else 2)

    for eg in espn_board:
        og_match: Optional[LiveMultiSportGame] = None
        best_idx_o: Optional[int] = None
        best_dt: float = float("inf")
        for idx_o, og in enumerate(official_board):
            if idx_o in used_off:
                continue
            dt_o = abs(float(eg.start_ts) - float(og.start_ts)) if (eg.start_ts > 0.0 and og.start_ts > 0.0) else 0.0
            if eg.start_ts > 0.0 and og.start_ts > 0.0 and dt_o > 5400.0:
                continue
            if _team_tokens_match(eg.home_name, og.home_name) and _team_tokens_match(eg.away_name, og.away_name):
                if dt_o < best_dt:
                    best_dt = dt_o
                    og_match = og
                    best_idx_o = idx_o
        if og_match is None or best_idx_o is None:
            merged.append(eg)
            continue
        used_off.add(best_idx_o)

        scores_eq = (eg.home_score == og_match.home_score) and (eg.away_score == og_match.away_score)
        both_final = bool(eg.completed and og_match.completed and scores_eq)
        off_ahead_final = bool(
            og_match.completed
            and not eg.completed
            and og_match.period >= min_reg_period
            and eg.period >= min_reg_period
            and og_match.home_score != og_match.away_score
            and og_match.home_score >= eg.home_score
            and og_match.away_score >= eg.away_score
        )
        if both_final or off_ahead_final:
            merged.append(
                LiveMultiSportGame(
                    sport=eg.sport,
                    game_id=eg.game_id,
                    start_ts=eg.start_ts or og_match.start_ts,
                    state="post",
                    completed=True,
                    is_halftime=False,
                    period=max(eg.period, og_match.period),
                    clock_sec=0.0,
                    home_name=eg.home_name,
                    away_name=eg.away_name,
                    home_score=og_match.home_score,
                    away_score=og_match.away_score,
                    linescores_home=eg.linescores_home or og_match.linescores_home,
                    linescores_away=eg.linescores_away or og_match.linescores_away,
                )
            )
        else:
            ls_h_min = dict(eg.linescores_home)
            for k_p, v_p in (og_match.linescores_home or {}).items():
                ls_h_min[k_p] = min(ls_h_min[k_p], v_p) if k_p in ls_h_min else v_p
            ls_a_min = dict(eg.linescores_away)
            for k_p, v_p in (og_match.linescores_away or {}).items():
                ls_a_min[k_p] = min(ls_a_min[k_p], v_p) if k_p in ls_a_min else v_p
            merged.append(
                LiveMultiSportGame(
                    sport=eg.sport,
                    game_id=eg.game_id,
                    start_ts=eg.start_ts or og_match.start_ts,
                    state="in",
                    completed=False,
                    is_halftime=bool(eg.is_halftime and og_match.is_halftime),
                    period=min(eg.period, og_match.period) if (eg.period > 0 and og_match.period > 0) else max(eg.period, og_match.period),
                    clock_sec=max(eg.clock_sec, og_match.clock_sec),
                    home_name=eg.home_name,
                    away_name=eg.away_name,
                    home_score=min(eg.home_score, og_match.home_score),
                    away_score=min(eg.away_score, og_match.away_score),
                    linescores_home=ls_h_min,
                    linescores_away=ls_a_min,
                )
            )

    for idx_o, og in enumerate(official_board):
        if idx_o not in used_off:
            merged.append(og)
    return merged


def parse_atp_wta_scoreboard(payload: Dict[str, Any], *, tour: str = "atp") -> List[Dict[str, Any]]:
    """
    Parses public ESPN ATP/WTA live scoreboard JSON into structured tennis match records
    (`completed_sets`, `status_state`, `retired_or_walkover`, `winner_name`) for `TEN1` / `Family G`.
    """
    out: List[Dict[str, Any]] = []
    for ev in (payload or {}).get("events") or []:
        if not isinstance(ev, dict):
            continue
        for grp in ev.get("groupings") or [ev]:
            for comp in grp.get("competitions") or []:
                if not isinstance(comp, dict):
                    continue
                st_type = ((comp.get("status") or {}).get("type") or {})
                state = str(st_type.get("state") or "").lower()
                detail = str(st_type.get("detail") or st_type.get("shortDetail") or "").lower()
                completed = bool(st_type.get("completed", state == "post"))
                retired = any(k in detail for k in ("ret", "walkover", "w/o", "default", "abandon"))
                competitors = comp.get("competitors") or []
                if len(competitors) < 2:
                    continue
                players: List[Dict[str, Any]] = []
                max_sets_done = 0
                winner_name = ""
                for c in competitors[:2]:
                    ath = c.get("athlete") or c.get("team") or {}
                    nm = str(ath.get("displayName") or ath.get("shortName") or "").strip()
                    sets = c.get("linescores") or []
                    sets_won = sum(1 for ls in sets if isinstance(ls, dict) and ls.get("winner") is True)
                    max_sets_done = max(max_sets_done, sum(1 for ls in sets if isinstance(ls, dict) and ls.get("winner") is not None))
                    is_win = bool(c.get("winner"))
                    if is_win and nm:
                        winner_name = nm
                    players.append({"name": nm, "sets_won": sets_won, "winner": is_win})
                out.append(
                    {
                        "tour": tour.upper(),
                        "match_id": str(comp.get("id") or ev.get("id") or ""),
                        "state": state or ("post" if completed else "in"),
                        "completed": completed,
                        "completed_sets": max_sets_done,
                        "retired_or_walkover": retired,
                        "winner_name": winner_name,
                        "players": players,
                    }
                )
    return out


def fetch_atp_wta_live_scores_sync(tour: str = "atp", *, timeout: float = 2.5) -> List[Dict[str, Any]]:
    """Fetches `$0/mo` public ATP or WTA live scores with conditional ETag caching."""
    t = "wta" if str(tour or "").strip().lower() == "wta" else "atp"
    try:
        payload = _get_conditional_json_sync(ESPN_TENNIS_SCOREBOARD_TMPL.format(tour=t), timeout=timeout)
        if isinstance(payload, dict):
            return parse_atp_wta_scoreboard(payload, tour=t)
    except Exception as exc:
        logger.debug(f"Tennis ({t}) direct feed notice: {exc}")
    return []

# ======================================================================================
# [18/68] MODULE: src/polymarket_research/latency_trace.py
# PURPOSE: Zero-Allocation Hot-Path Microsecond Latency Tracer & Stage Breakdown Telemetry
# ======================================================================================

"""
End-to-end latency tracing for the Polymarket live hot path (Phase 0 instrumentation).

Design goals
------------
* Zero risk to trading: every public call is non-blocking and swallows its own errors.
* Three clock domains are recorded and must never be mixed up:
    - local monotonic (`time.perf_counter_ns`)  -> elapsed stage durations on this host only
    - local wall (`time.time_ns`)               -> cross-process / cross-host alignment (needs chrony)
    - source/exchange timestamps                -> stored verbatim as `src_*` fields
* One JSONL record per `execute_snipe_order_async` dispatch attempt, written by a daemon thread.

Output file: `$PM_LATENCY_TRACE_FILE`, else `$PM_TELEMETRY_DIR/latency_trace.jsonl`,
else `data/polymarket/latency_trace.jsonl`. Disable entirely with `PM_LATENCY_TRACE=0`.

Analyse with `python scripts/latency_trace_report.py`.
"""

# from __future__ import annotations  # (Lifted to top of consolidated bundle)

import atexit
import contextvars
import json
import logging
import os
import queue
import threading
import time
from pathlib import Path
from typing import Any, Dict, Optional

try:
    import orjson as _orjson
except ImportError:  # pragma: no cover
    _orjson = None

logger = logging.getLogger(__name__)

_WRITER_LOCK = threading.Lock()
_WRITER_QUEUE: "queue.SimpleQueue[tuple[str, str]]" = queue.SimpleQueue()
_WRITER_THREAD: Optional[threading.Thread] = None
_QUEUE_SOFT_LIMIT = 5000
_pending = 0
_pending_lock = threading.Lock()


def tracing_enabled() -> bool:
    return os.environ.get("PM_LATENCY_TRACE", "1").strip().lower() not in ("0", "false", "no", "off")


def trace_path() -> Path:
    explicit = os.environ.get("PM_LATENCY_TRACE_FILE")
    if explicit:
        return Path(explicit)
    tele = os.environ.get("PM_TELEMETRY_DIR")
    if tele:
        return Path(tele) / "latency_trace.jsonl"
    return Path("data") / "polymarket" / "latency_trace.jsonl"


def shock_attempt_path() -> Path:
    explicit = os.environ.get("PM_SHOCK_ATTEMPT_FILE")
    if explicit:
        return Path(explicit)
    tele = os.environ.get("PM_TELEMETRY_DIR")
    if tele:
        return Path(tele) / "shock_attempt_forensics.jsonl"
    return Path("data") / "polymarket" / "shock_attempt_forensics.jsonl"


def _writer_loop() -> None:
    global _pending
    while True:
        try:
            first_item = _WRITER_QUEUE.get()
            batch_items = [first_item]
            deadline = time.monotonic() + 0.25
            while len(batch_items) < 200 and time.monotonic() < deadline:
                try:
                    batch_items.append(_WRITER_QUEUE.get(timeout=0.05))
                except queue.Empty:
                    break
            try:
                by_dest: Dict[str, list[str]] = {}
                for dest_s, ln in batch_items:
                    by_dest.setdefault(dest_s, []).append(ln)
                for dest_s, lines_out in by_dest.items():
                    try:
                        path = Path(dest_s)
                        path.parent.mkdir(parents=True, exist_ok=True)
                        with open(path, "a", encoding="utf-8") as fh:
                            fh.write("\n".join(lines_out) + "\n")
                    except Exception:
                        pass
            finally:
                with _pending_lock:
                    _pending = max(0, _pending - len(batch_items))
        except Exception:  # never let telemetry kill anything
            time.sleep(0.5)


def _ensure_writer() -> None:
    global _WRITER_THREAD
    if _WRITER_THREAD is not None and _WRITER_THREAD.is_alive():
        return
    with _WRITER_LOCK:
        if _WRITER_THREAD is not None and _WRITER_THREAD.is_alive():
            return
        t = threading.Thread(target=_writer_loop, name="pm-latency-trace-writer", daemon=True)
        t.start()
        _WRITER_THREAD = t


def flush(timeout: float = 2.0) -> None:
    """Best-effort wait until queued records are written (used by tests / shutdown)."""
    end = time.monotonic() + timeout
    while time.monotonic() < end:
        with _pending_lock:
            if _pending == 0:
                return
        time.sleep(0.02)


atexit.register(flush)


class LatencyTrace:
    """Collects monotonic stamps + scalar fields for one trigger -> dispatch journey."""

    __slots__ = ("fields", "stamps_ns", "created_mono_ns", "created_wall_ns", "attempt")

    def __init__(self, **fields: Any) -> None:
        self.fields: Dict[str, Any] = dict(fields)
        self.stamps_ns: Dict[str, int] = {}
        self.created_mono_ns = time.perf_counter_ns()
        self.created_wall_ns = time.time_ns()
        self.attempt = 0

    def stamp(self, name: str) -> None:
        try:
            self.stamps_ns[name] = time.perf_counter_ns()
        except Exception:
            pass

    def set(self, **kv: Any) -> None:
        try:
            self.fields.update(kv)
        except Exception:
            pass

    def elapsed_ms(self, a: str, b: str) -> Optional[float]:
        sa, sb = self.stamps_ns.get(a), self.stamps_ns.get(b)
        if sa is None or sb is None:
            return None
        return (sb - sa) / 1e6

    def to_record(self) -> Dict[str, Any]:
        rec: Dict[str, Any] = dict(self.fields)
        rec["attempt"] = self.attempt
        rec["created_wall_ns"] = self.created_wall_ns
        # Stamps are stored relative to trace creation (monotonic, same-host only).
        rec["stamps_rel_ms"] = {
            k: round((v - self.created_mono_ns) / 1e6, 4) for k, v in self.stamps_ns.items()
        }
        return rec

    def emit(self, **final_fields: Any) -> None:
        """Queue one JSONL record. Non-blocking, never raises."""
        global _pending
        try:
            if not tracing_enabled():
                return
            if final_fields:
                self.fields.update(final_fields)
            self.stamp("emit")
            rec = self.to_record()
            if _orjson is not None:
                try:
                    line = _orjson.dumps(rec, default=str).decode("utf-8")
                except Exception:
                    line = json.dumps(rec, default=str, separators=(",", ":"))
            else:
                line = json.dumps(rec, default=str, separators=(",", ":"))
            dest_str = str(trace_path())
            with _pending_lock:
                if _pending >= _QUEUE_SOFT_LIMIT:
                    return  # drop rather than grow unbounded
                _pending += 1
            _ensure_writer()
            _WRITER_QUEUE.put((dest_str, line))
            self.attempt += 1
        except Exception:
            logger.debug("latency trace emit failed", exc_info=True)


# Carries the active trace from the harvester coroutine into executor.execute_snipe_order_async
# without changing either public signature.
CURRENT_TRACE: "contextvars.ContextVar[Optional[LatencyTrace]]" = contextvars.ContextVar(
    "pm_current_latency_trace", default=None
)


class ActiveCounter:
    """
    Thread-safe re-entrant activity counter replacing a process-global Event.

    The hot pool has several workers; with an Event the first finisher cleared the flag while
    another POST was still in flight, letting background socket warming collide with it.
    """

    __slots__ = ("_n", "_lock")

    def __init__(self) -> None:
        self._n = 0
        self._lock = threading.Lock()

    def enter(self) -> None:
        with self._lock:
            self._n += 1

    def leave(self) -> None:
        with self._lock:
            self._n = max(0, self._n - 1)

    exit = leave

    def __enter__(self) -> "ActiveCounter":
        self.enter()
        return self

    def __exit__(self, exc_type: Any, exc: Any, tb: Any) -> bool:
        self.leave()
        return False

    def is_set(self) -> bool:  # Event-compatible read API for existing call sites
        return self._n > 0

    @property
    def count(self) -> int:
        return self._n


def _fin_float(val: Any, default: Optional[float] = None) -> Optional[float]:
    if val is None or isinstance(val, bool):
        return default
    try:
        f = float(val)
        return f if f == f and abs(f) != float("inf") else default
    except (TypeError, ValueError):
        return default


def classify_shock_attempt(raw: Dict[str, Any]) -> Dict[str, Any]:
    """
    Pure root-cause & speed attribution classifier for directional shocks and order attempts.
    Answers explicitly whether a missed trade failed due to latency/speed (flight repricing,
    pre-eval MM repricing, or feed/IPC lag), passive Maker runaway, adverse shield protection,
    already-priced-in market quotes, or intentional WFO alpha/governance guardrails.
    """
    now_u = _fin_float(raw.get("unix_ts"), time.time()) or time.time()
    ts_utc = str(raw.get("ts_utc") or time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime(now_u)))
    asset = str(raw.get("asset") or "").upper()
    horizon = str(raw.get("horizon") or "").lower()
    raw_tt = str(raw.get("target_token") or "").upper()
    raw_sd = str(raw.get("side") or "").upper()
    side = raw_tt if (raw_tt and raw_sd in ("", "BUY", "SELL")) else (raw_sd or raw_tt)
    path_type = str(raw.get("path_type") or "PRE_EVAL").upper()
    gate_code = str(raw.get("gate_code") or "").upper()
    _raw_gd = str(raw.get("gate_detail") or "").strip()
    if not _raw_gd and raw.get("diagnosis"):
        _diag_in = str(raw.get("diagnosis") or "").strip()
        for _pfx in ("Feed/IPC lag blocked entry", "TOO SLOW (MM Beat Shock)"):
            if _diag_in.startswith(_pfx) and "): " in _diag_in:
                _diag_in = _diag_in.split("): ", 1)[1].strip()
                break
            if _diag_in.startswith(_pfx) and ": " in _diag_in:
                _diag_in = _diag_in.split(": ", 1)[1].strip()
                break
        _raw_gd = _diag_in
    gate_detail = _raw_gd
    stage_out = str(raw.get("stage_outcome") or raw.get("outcome") or "").upper()

    tte_s = _fin_float(raw.get("tte_s"))
    dist_pct = _fin_float(raw.get("dist_pct"))
    z_strike = _fin_float(raw.get("z_strike"))
    obi_l1 = _fin_float(raw.get("obi_l1"))
    t0_ask = _fin_float(raw.get("t0_ask"))
    eval_ask = _fin_float(raw.get("eval_ask"))
    eval_bid = _fin_float(raw.get("eval_bid"))
    target_px = _fin_float(raw.get("target_px") if raw.get("target_px") is not None else raw.get("target_limit_px"))
    cap_px = _fin_float(raw.get("cap_px"))
    post_ask = _fin_float(raw.get("post_ask"))
    post_bid = _fin_float(raw.get("post_bid"))
    fill_px = _fin_float(raw.get("fill_px"))
    notional_usd = _fin_float(raw.get("notional_usd") if raw.get("notional_usd") is not None else raw.get("effective_notional_usd"))

    exch_lag_ms = _fin_float(raw.get("exch_lag_ms"))
    ipc_ms = _fin_float(raw.get("ipc_ms") if raw.get("ipc_ms") is not None else raw.get("trigger_to_consume_wall_ms"))
    book_age_ms = _fin_float(raw.get("book_age_ms") if raw.get("book_age_ms") is not None else raw.get("age_ask_ms"))
    empty_ask_ms = _fin_float(raw.get("empty_ask_ms"))
    ws_book_age_ms = _fin_float(raw.get("ws_book_age_ms"))
    gate_ms = _fin_float(raw.get("gate_ms"))
    sign_ms = _fin_float(raw.get("sign_ms"))
    http_ms = _fin_float(raw.get("http_ms") if raw.get("http_ms") is not None else raw.get("clob_http_post_ms"))
    ttl_ms = _fin_float(raw.get("ttl_ms"))
    presign_hit = bool(raw.get("presign_cache_hit", False))

    e2e_parts = [x for x in (exch_lag_ms, ipc_ms, gate_ms, sign_ms, http_ms) if x is not None and x >= 0.0]
    e2e_ms = round(sum(e2e_parts), 2) if e2e_parts else None

    ask_drift_pre_c = round((eval_ask - t0_ask) * 100.0, 1) if (eval_ask and t0_ask and eval_ask > 0 and t0_ask > 0) else None
    ref_pre_flight_ask = eval_ask if (eval_ask and eval_ask > 0) else t0_ask
    ask_drift_flight_c = (
        round((post_ask - ref_pre_flight_ask) * 100.0, 1)
        if (post_ask and ref_pre_flight_ask and post_ask > 0 and ref_pre_flight_ask > 0)
        else None
    )

    if stage_out in ("FILLED_TAKER", "POSTED", "MATCHED") and str(raw.get("resp_status") or "matched").lower() in ("matched", "filled", ""):
        if path_type == "PRE_EVAL":
            path_type = "TAKER_FOK"
    elif stage_out in ("FAK_KILLED", "FAK_KILLED_NO_MATCH") and path_type == "PRE_EVAL":
        path_type = "TAKER_FOK"
    elif "MAKER" in stage_out and path_type == "PRE_EVAL":
        path_type = "MAKER_P3A"

    is_order_attempt = path_type in ("TAKER_FOK", "MAKER_P3A", "MAKER_BOX")
    speed_verdict = "ALPHA_GATE_VETO"
    badge = "GATE VETO"
    diagnosis = gate_detail or gate_code or "Filtered by strategy guardrail"

    def _lat_tag() -> str:
        bits = []
        if exch_lag_ms is not None:
            bits.append(f"Exch {exch_lag_ms:.0f}ms")
        if ipc_ms is not None:
            bits.append(f"IPC {ipc_ms:.1f}ms")
        if sign_ms is not None:
            bits.append(f"Sign {sign_ms:.2f}ms")
        if http_ms is not None:
            bits.append(f"HTTP {http_ms:.0f}ms")
        return ", ".join(bits) if bits else "n/a"

    if stage_out in ("FILLED_TAKER", "FILLED_MAKER", "FILLED_BOX") or (
        stage_out == "POSTED" and str(raw.get("resp_status") or "").lower() == "matched"
    ):
        speed_verdict = "FILLED"
        badge = "FILLED"
        px_show = fill_px or target_px or eval_ask or 0.0
        diagnosis = f"Filled @ ${px_show:.3f}" + (f" (${notional_usd:.2f})" if notional_usd else "") + f" [{_lat_tag()}]"

    elif stage_out in ("FAK_KILLED", "FAK_KILLED_NO_MATCH"):
        speed_verdict = "TOO_SLOW_FLIGHT"
        badge = "TOO SLOW (FLIGHT)"
        lim_s = f"${target_px:.2f}" if target_px else "limit"
        ev_s = f"${eval_ask:.2f}" if eval_ask else (f"${t0_ask:.2f}" if t0_ask else "?")
        if post_ask and target_px and post_ask > target_px + 0.005:
            jump_c = (post_ask - (eval_ask or target_px)) * 100.0
            diagnosis = f"TOO SLOW (Flight): FOK @{lim_s} (eval {ev_s}) missed — MM repriced ask -> ${post_ask:.2f} ({jump_c:+.1f}c) during flight ({_lat_tag()})"
        else:
            diagnosis = f"TOO SLOW (Flight): FOK @{lim_s} (eval {ev_s}) 0-fill — L1 liquidity swept ahead during flight ({_lat_tag()})"

    elif stage_out in ("MAKER_POST_FAILED", "BOND1_MAKER_POST_FAILED", "HTTP_400", "CLOB_HTTP_400_REJECTION"):
        err_l = gate_detail.lower()
        if any(k in err_l for k in ("crosses book", "post only", "post-only")):
            speed_verdict = "TOO_SLOW_FLIGHT"
            badge = "POST-ONLY CROSSED"
            diagnosis = f"Book crossed Maker bid ${target_px or 0:.3f} during HTTP flight ({_lat_tag()}): {gate_detail[:90]}"
        else:
            speed_verdict = "CLOB_REJECT"
            badge = "CLOB 400 REJECT"
            diagnosis = f"CLOB rejected order @${target_px or 0:.3f}: {gate_detail[:110] or stage_out}"

    elif stage_out in ("SHIELD_PRE_POST", "SHIELD_ADVERSE_TTL", "BOND1_MAKER_ADVERSE_CANCELLED"):
        speed_verdict = "SHIELD_SAVED"
        badge = "SHIELD SAVED"
        diagnosis = gate_detail or (
            "Pre-post shield aborted Maker: spot retraced >25% before post"
            if stage_out == "SHIELD_PRE_POST"
            else f"Mid-TTL adverse shield canceled Maker @{f'${target_px:.3f}' if target_px else ''} before toxic fill"
        )

    elif stage_out == "BOND1_MAKER_OUTBID_RELEASED":
        ttl_s_lbl = f"{(ttl_ms or 0.0) / 1000.0:.1f}s" if ttl_ms else "TTL"
        speed_verdict = "ALPHA_GATE_VETO"
        badge = "OUTBID RELEASED"
        diagnosis = (
            f"Released outbid 0%-fee Maker @${target_px or 0:.3f} after {ttl_s_lbl} "
            f"to free collateral ({gate_detail or 'outbid above cap'}) [{_lat_tag()}]"
        )

    elif stage_out in ("MAKER_TTL_EXPIRED", "BOND1_MAKER_EXPIRED_UNFILLED", "BOND1_MAKER_PREEMPTED"):
        ttl_s_lbl = f"{(ttl_ms or 0.0) / 1000.0:.1f}s" if ttl_ms else "TTL"
        if stage_out == "BOND1_MAKER_PREEMPTED":
            speed_verdict = "MAKER_TTL_QUIET"
            badge = "MAKER PREEMPTED"
            diagnosis = (
                f"Preempted resting 0%-fee Maker @${target_px or 0:.3f} after {ttl_s_lbl} "
                f"to free collateral ({gate_detail or 'priority entry'}) [{_lat_tag()}]"
            )
        elif path_type == "MAKER_P3A" and post_ask and target_px and (
            post_ask >= target_px + 0.03 or (eval_ask and post_ask >= eval_ask + 0.02)
        ):
            speed_verdict = "LEFT_BEHIND_MAKER"
            badge = "LEFT BEHIND (MAKER)"
            ev_s = f"${eval_ask:.2f}" if eval_ask else f"${target_px + 0.01:.2f}"
            diagnosis = (
                f"LEFT BEHIND: Posted 0%-fee Maker @${target_px:.2f} ({_lat_tag()}); "
                f"ask ran {ev_s} -> ${post_ask:.2f} ({(post_ask - (eval_ask or target_px))*100:+.0f}c) over {ttl_s_lbl} without pullback"
            )
        else:
            speed_verdict = "MAKER_TTL_QUIET"
            badge = "MAKER TTL QUIET"
            end_s = f" (end ask ${post_ask:.3f})" if post_ask else ""
            diagnosis = f"Resting 0%-fee Maker @${target_px or 0:.3f} unfilled after {ttl_s_lbl}, canceled cleanly{end_s} [{_lat_tag()}]"

    elif gate_code == "NO_RESTING_ASKS":
        speed_verdict = "ALPHA_GATE_VETO"
        badge = "NO ASKS"
        diagnosis = gate_detail or "Empty ask book at t0 — not a speed miss"

    elif (
        gate_code == "COMPOSITE_EDGE_VETO"
        and "AGE_ASK_MS" in gate_detail.upper()
        and t0_ask is not None
        and t0_ask >= 0.995
    ):
        speed_verdict = "ALREADY_PRICED_IN"
        badge = "ALREADY PRICED IN"
        diagnosis = f"Already Priced In: No resting asks < $1.00 at t0 ({_lat_tag()}) — not a speed miss"

    elif gate_code == "COMPOSITE_EDGE_VETO" and (
        "REPRICED BY MM" in gate_detail.upper() or "MM ASK RELOAD" in gate_detail.upper()
    ):
        _mm_px = eval_ask if eval_ask is not None else t0_ask
        _mm_cap = cap_px if (cap_px is not None and cap_px > 0.0) else (0.72 if "15" in horizon else 0.76)
        _mm_jumped = bool(ask_drift_pre_c is not None and ask_drift_pre_c >= 1.9)
        if _mm_px is not None and _mm_px >= max(0.88, _mm_cap + 0.12) and not _mm_jumped:
            speed_verdict = "ALREADY_PRICED_IN"
            badge = "ALREADY PRICED IN"
            diagnosis = (
                f"Already Priced In: Ask already deep ITM @${_mm_px:.2f} (> ${_mm_cap:.2f} cap) "
                f"before shock ({_lat_tag()}) — not a speed miss"
            )
        else:
            speed_verdict = "TOO_SLOW_PRE_EVAL"
            badge = "TOO SLOW (PRE-EVAL)"
            diagnosis = f"TOO SLOW (MM Beat Shock): {gate_detail} ({_lat_tag()})"

    elif gate_code in ("EXCHANGE_LAG_REJECT", "STALE_TRIGGER_INGRESS"):
        speed_verdict = "TOO_SLOW_FEED_LAG"
        badge = "FEED / IPC LAG"
        diagnosis = f"Feed/IPC lag blocked entry ({_lat_tag()}): {gate_detail or gate_code}"

    elif gate_code in (
        "CLOB_WS_DISCONNECTED",
        "STALE_RECORDER_GUARD",
        "SLOW_REST_BOOK",
    ) or ("MISSING LIVE MICROSTRUCTURE" in gate_detail.upper() or "AGE_ASK_MS" in gate_detail.upper()):
        _lag_px = eval_ask if eval_ask is not None else t0_ask
        if _lag_px is not None and _lag_px >= 0.985 and not (ask_drift_pre_c is not None and ask_drift_pre_c >= 1.9):
            speed_verdict = "ALREADY_PRICED_IN"
            badge = "ALREADY PRICED IN"
            diagnosis = f"Already Priced In: Book already pinned @${_lag_px:.3f} before shock ({_lat_tag()}) — not a speed miss"
        else:
            speed_verdict = "TOO_SLOW_FEED_LAG"
            badge = "FEED / IPC LAG"
            diagnosis = f"Feed/IPC lag blocked entry ({_lat_tag()}): {gate_detail or gate_code}"

    elif gate_code in (
        "TAKER_ASYMMETRY_VETO",
        "15M_MAKER_INELIGIBLE",
        "EV_CEILING_REJECT",
        "PRICE_BAND_REJECT",
        "VWAP_BAND_REJECT",
        "P_MAX_REJECT",
    ):
        px_now = eval_ask or t0_ask or 0.0
        cap_s = f"${cap_px:.2f}" if cap_px else "cap"
        jumped_since_t0 = bool(ask_drift_pre_c is not None and ask_drift_pre_c >= 1.9)
        just_repriced_by_mm = bool(
            book_age_ms is not None
            and 0.0 <= book_age_ms <= 350.0
            and (cap_px is None or px_now <= cap_px + 0.12)
        )
        just_swept_empty = bool(
            px_now >= 0.995 and empty_ask_ms is not None and 0.0 <= empty_ask_ms <= 350.0
        )
        _pinned_floor = cap_px if (cap_px is not None and cap_px > 0.0) else 0.80
        if just_swept_empty:
            speed_verdict = "TOO_SLOW_PRE_EVAL"
            badge = "TOO SLOW (PRE-EVAL)"
            diagnosis = (
                f"TOO SLOW (Swept Empty): Asks swept to empty {empty_ask_ms:.0f}ms ago "
                f"before dispatch ({_lat_tag()})"
            )
        elif px_now >= 0.995 and eval_bid is not None and eval_bid >= _pinned_floor and not jumped_since_t0:
            speed_verdict = "ALREADY_PRICED_IN"
            badge = "ALREADY PRICED IN"
            diagnosis = f"Already Priced In: Book pinned @${eval_bid:.2f} bid / no asks < $1.00 before shock — not a speed miss"
        elif jumped_since_t0 or just_repriced_by_mm:
            speed_verdict = "TOO_SLOW_PRE_EVAL"
            badge = "TOO SLOW (PRE-EVAL)"
            if jumped_since_t0 and t0_ask:
                diagnosis = (
                    f"TOO SLOW (Pre-Eval): Ask jumped ${t0_ask:.2f} -> ${px_now:.2f} (+{ask_drift_pre_c:.1f}c > {cap_s}) "
                    f"before dispatch ({_lat_tag()})"
                )
            else:
                diagnosis = (
                    f"TOO SLOW (MM Beat Shock): MM repriced ask {book_age_ms:.0f}ms ago to ${px_now:.2f} > {cap_s} "
                    f"before trigger arrived ({_lat_tag()})"
                )
        elif cap_px and px_now < cap_px and eval_bid and eval_bid > cap_px:
            speed_verdict = "ALREADY_PRICED_IN"
            badge = "ABOVE CAP"
            diagnosis = f"Bid ${eval_bid:.2f} / Ask ${px_now:.2f} already above {cap_s} ceiling"
        else:
            speed_verdict = "ALREADY_PRICED_IN"
            badge = "ALREADY PRICED IN"
            age_s = f" for {book_age_ms/1000.0:.1f}s" if (book_age_ms and book_age_ms >= 400.0) else ""
            diagnosis = f"Already Priced In: Book sat @${px_now:.2f}{age_s} (> {cap_s}) before shock — not a speed miss"

    elif gate_code == "SHADOW_ASSET_PAUSED":
        speed_verdict = "SHADOW_RECORDED"
        badge = "SHADOW ONLY"
        path_type = "SHADOW"
        diagnosis = f"{asset} live directional paused in v5.2; logged to shadow ledger (ask ${t0_ask or 0:.2f}, dist {dist_pct or 0:+.3f}%)"

    elif gate_code == "WFO_Z_CUSHION":
        speed_verdict = "ALPHA_GATE_VETO"
        badge = "WFO Z-GATE"
        diagnosis = gate_detail or f"z_strike={z_strike or 0:.2f} below WFO floor (dist {dist_pct or 0:+.3f}%, TTE {tte_s or 0:.0f}s)"

    elif gate_code == "COMPOSITE_EDGE_VETO":
        speed_verdict = "ALPHA_GATE_VETO"
        badge = "OBI / EDGE VETO"
        diagnosis = gate_detail or f"Composite microstructure veto (obi_l1={obi_l1 or 0:+.2f})"

    elif gate_code in ("15M_TTE_WINDOW", "1H_TTE_WINDOW", "TTE_OUT_OF_RANGE"):
        speed_verdict = "ALPHA_GATE_VETO"
        badge = "TTE WINDOW"
        diagnosis = gate_detail or f"TTE {tte_s or 0:.0f}s outside allowed entry window"

    elif gate_code == "CUSHION_TOO_SMALL":
        speed_verdict = "ALPHA_GATE_VETO"
        badge = "THIN CUSHION"
        diagnosis = gate_detail or f"Spot distance {dist_pct or 0:+.4f}% insufficient / opposing {side} shock"

    else:
        speed_verdict = "ALPHA_GATE_VETO"
        badge = gate_code[:18].replace("_", " ") if gate_code else "GATE VETO"
        diagnosis = gate_detail or gate_code or "Filtered prior to dispatch"

    _px_settled = eval_ask if eval_ask is not None else t0_ask
    is_settled_99c = bool(
        speed_verdict == "ALREADY_PRICED_IN"
        and _px_settled is not None
        and (
            (0.985 <= _px_settled < 0.995)
            or (_px_settled >= 0.995 and (eval_bid is None or eval_bid >= 0.98))
            or (eval_bid is not None and eval_bid >= 0.98 and _px_settled >= 0.985)
        )
    )
    if is_settled_99c:
        badge = "SETTLED 99c+"

    is_speed_miss = speed_verdict in ("TOO_SLOW_FLIGHT", "TOO_SLOW_PRE_EVAL", "TOO_SLOW_FEED_LAG", "LEFT_BEHIND_MAKER")
    meaningful = bool(
        is_order_attempt
        or is_speed_miss
        or speed_verdict in ("SHIELD_SAVED", "CLOB_REJECT", "SHADOW_RECORDED")
        or (speed_verdict == "ALREADY_PRICED_IN" and not is_settled_99c)
        or (
            not is_settled_99c
            and gate_code not in ("CUSHION_TOO_SMALL", "TTE_OUT_OF_RANGE", "1H_TTE_WINDOW", "15M_TTE_WINDOW", "MARKET_DEDUP", "CONCURRENCY_LIMIT")
            and (dist_pct is None or abs(dist_pct) >= 0.04)
        )
    )

    return {
        "ts_utc": ts_utc,
        "unix_ts": round(now_u, 3),
        "shock_id": str(raw.get("shock_id") or ""),
        "trade_id": str(raw.get("trade_id") or ""),
        "asset": asset,
        "horizon": horizon,
        "side": side,
        "market_id": str(raw.get("market_id") or ""),
        "title": str(raw.get("title") or "")[:72],
        "sleeve": str(raw.get("sleeve") or ""),
        "path_type": path_type,
        "gate_code": gate_code,
        "stage_outcome": stage_out,
        "speed_verdict": speed_verdict,
        "badge": badge,
        "is_speed_miss": is_speed_miss,
        "is_order_attempt": is_order_attempt,
        "meaningful": meaningful,
        "tte_s": round(tte_s, 1) if tte_s is not None else None,
        "dist_pct": round(dist_pct, 4) if dist_pct is not None else None,
        "z_strike": round(z_strike, 3) if z_strike is not None else None,
        "obi_l1": round(obi_l1, 3) if obi_l1 is not None else None,
        "t0_ask": round(t0_ask, 4) if t0_ask is not None else None,
        "eval_ask": round(eval_ask, 4) if eval_ask is not None else None,
        "eval_bid": round(eval_bid, 4) if eval_bid is not None else None,
        "target_px": round(target_px, 4) if target_px is not None else None,
        "cap_px": round(cap_px, 4) if cap_px is not None else None,
        "post_ask": round(post_ask, 4) if post_ask is not None else None,
        "post_bid": round(post_bid, 4) if post_bid is not None else None,
        "fill_px": round(fill_px, 4) if fill_px is not None else None,
        "notional_usd": round(notional_usd, 2) if notional_usd is not None else None,
        "ask_drift_pre_c": ask_drift_pre_c,
        "ask_drift_flight_c": ask_drift_flight_c,
        "exch_lag_ms": round(exch_lag_ms, 1) if exch_lag_ms is not None else None,
        "ipc_ms": round(ipc_ms, 2) if ipc_ms is not None else None,
        "book_age_ms": round(book_age_ms, 1) if book_age_ms is not None else None,
        "ws_book_age_ms": round(ws_book_age_ms, 1) if ws_book_age_ms is not None else None,
        "gate_ms": round(gate_ms, 2) if gate_ms is not None else None,
        "sign_ms": round(sign_ms, 3) if sign_ms is not None else None,
        "http_ms": round(http_ms, 2) if http_ms is not None else None,
        "ttl_ms": round(ttl_ms, 1) if ttl_ms is not None else None,
        "e2e_ms": e2e_ms,
        "presign_hit": presign_hit,
        "diagnosis": diagnosis,
    }


def emit_shock_attempt(raw: Dict[str, Any]) -> Optional[Dict[str, Any]]:
    """Non-blocking background write to `shock_attempt_forensics.jsonl`."""
    global _pending
    try:
        if not tracing_enabled():
            return None
        if raw.get("skip_forensic"):
            return None
        if raw.get("dry_run") and not os.environ.get("PM_SHOCK_ATTEMPT_FILE"):
            return None
        rec = classify_shock_attempt(raw)
        if _orjson is not None:
            try:
                line = _orjson.dumps(rec, default=str).decode("utf-8")
            except Exception:
                line = json.dumps(rec, default=str, separators=(",", ":"))
        else:
            line = json.dumps(rec, default=str, separators=(",", ":"))
        dest_str = str(shock_attempt_path())
        with _pending_lock:
            if _pending >= _QUEUE_SOFT_LIMIT:
                return rec
            _pending += 1
        _ensure_writer()
        _WRITER_QUEUE.put((dest_str, line))
        if rec.get("is_order_attempt") or rec.get("is_speed_miss"):
            logger.info(
                "[ATTEMPT FORENSICS] %s %s %s [%s] %s",
                rec.get("asset"),
                rec.get("horizon"),
                rec.get("side"),
                rec.get("badge"),
                rec.get("diagnosis"),
            )
        return rec
    except Exception:
        logger.debug("emit_shock_attempt failed", exc_info=True)
        return None


def emit_shock_attempt_from_trace(trace: Optional[LatencyTrace], shock: Optional[Dict[str, Any]] = None) -> Optional[Dict[str, Any]]:
    """Extracts monotonic timing + gate/attempt telemetry from `LatencyTrace` + `shock` and queues forensics."""
    try:
        if trace is None:
            return None
        f = dict(trace.fields)
        if f.get("skip_forensic"):
            return None
        shk = shock or {}
        s_dir = str(shk.get("shock_direction") or "").upper()
        f_tt = str(f.get("target_token") or "").upper()
        f_sd = str(f.get("side") or "").upper()
        side = f_tt or (f_sd if f_sd not in ("", "BUY", "SELL") else ("UP" if s_dir == "BUY" else ("DOWN" if s_dir == "SELL" else f_sd)))
        tf_t0 = ((shk.get("pre_shock_features_t0") or {}).get(side) or {}) if side else {}
        t0_u = _fin_float(shk.get("t0_unix"))
        exch_ms = _fin_float(shk.get("exchange_event_ts_ms"))
        exch_lag = ((t0_u * 1000.0) - exch_ms) if (t0_u and exch_ms and exch_ms > 0) else None
        gate_ms = trace.elapsed_ms("trigger_consumed", "dispatch_call")
        if gate_ms is None:
            s_c = trace.stamps_ns.get("trigger_consumed")
            if s_c is not None:
                gate_ms = (time.perf_counter_ns() - s_c) / 1e6

        _shk_age_ms = shk.get("age_ask_ms") if shk.get("age_ask_ms") is not None else tf_t0.get("age_ask_ms")
        merged: Dict[str, Any] = {
            "unix_ts": time.time(),
            "shock_id": f.get("shock_id") or shk.get("shock_id") or f"{shk.get('market_id')}_{shk.get('t0_unix')}",
            "market_id": f.get("market_id") or shk.get("market_id") or "",
            "title": f.get("title") or shk.get("title") or "",
            "asset": f.get("asset") or shk.get("asset") or "",
            "horizon": f.get("horizon") or shk.get("horizon") or shk.get("candle_interval") or "",
            "side": side,
            "tte_s": f.get("tte_s") if f.get("tte_s") is not None else shk.get("seconds_to_expiry"),
            "dist_pct": f.get("dist_pct") if f.get("dist_pct") is not None else shk.get("candle_distance_pct"),
            "t0_ask": f.get("t0_ask") if f.get("t0_ask") is not None else tf_t0.get("best_ask"),
            "book_age_ms": f.get("book_age_ms") if f.get("book_age_ms") is not None else _shk_age_ms,
            "empty_ask_ms": f.get("empty_ask_ms") if f.get("empty_ask_ms") is not None else tf_t0.get("empty_ask_ms"),
            "obi_l1": f.get("obi_l1") if f.get("obi_l1") is not None else tf_t0.get("obi_l1"),
            "exch_lag_ms": f.get("exch_lag_ms") if f.get("exch_lag_ms") is not None else exch_lag,
            "gate_ms": gate_ms,
        }
        merged.update(f)
        return emit_shock_attempt(merged)
    except Exception:
        logger.debug("emit_shock_attempt_from_trace failed", exc_info=True)
        return None

