# [26/68] MODULE: src/polymarket_research/verify_onchain_allowances.py
# PURPOSE: ERC-20/ERC-1155 Proxy & Exchange Allowance Verifier
# ======================================================================================

import os
import sys
from pathlib import Path
from dotenv import load_dotenv
from web3 import Web3
from web3.middleware import ExtraDataToPOAMiddleware

PIPELINE_ROOT = Path(__file__).resolve().parent.parent.parent
load_dotenv(PIPELINE_ROOT / ".env")

RPC = "https://polygon-bor-rpc.publicnode.com"
w3 = Web3(Web3.HTTPProvider(RPC))
try:
    w3.middleware_onion.inject(ExtraDataToPOAMiddleware, layer=0)
except Exception:
    pass

raw_wallet = os.getenv("POLYGON_FUNDER_ADDRESS", "").strip()
if not raw_wallet:
    print("[ERROR] POLYGON_FUNDER_ADDRESS not found in .env")
    sys.exit(1)
