    assert res_legout["success"] is False and res_legout["legged_out"] is True
    assert len(unwind_calls) == 1 and unwind_calls[0][0] == "tok_a"

    # 3. Smooth 18% dynamic compounding ($73.01 -> ~$13.14) + Shot-1 +2c FAK strictly <= p_max
