    weird.write_text(json.dumps({"max_exposure": -5, "max_daily_loss": "lots", "min_equity_floor": 70.0}))
    cfg = load_risk_config(weird)
    assert cfg["max_exposure"] == 35.00 and cfg["max_daily_loss"] == 20.00 and cfg["min_equity_floor"] == 70.0


