                    condition_id="0x" + "72" * 32,
                    side_label="NO",
                    display_label="Gas 0.998 2h",
                    bk_win={"bids": [{"price": "0.989", "size": "50"}], "asks": [{"price": "0.999", "size": "20"}]},
                    bk_opp={"bids": [], "asks": [{"price": "0.01", "size": "50"}]},
                    neg_risk=True,
                    close_ts=now_ts + 7200.0,
                    now_ts=now_ts,
